const STATE_REPORTS = {
  "Alabama": {"landscape": "Alabama does not have any community-owned solar policies.", "policies": {"vnm": {"status": "No", "text": "The state has not enabled net metering through any policies."}, "cs": {"status": "No", "text": "Alabama has no policies explicitly targeting community solar. However, small cooperatives have emerged in certain areas of the state. These programs allow subscribers to pay either a reduced rate multiplied by their total real electric use or a fixed fee for a set amount of solar power."}, "other": {"status": "No", "text": "The state has not enabled community-owned solar through any policies. Existing private community solar cooperatives do not appear to offer a community ownership option. In addition, Alabama was not afforded a Solar For All grant by the EPA. However, the state is part of the Community Power Coalition, Clean Energy Fund of Texas, and Southeast Rural Power Coalition, which were afforded $249 million, $156 million, and $156 million, respectively, under the SFA."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The state has several private solar cooperatives, including the Covington Electric Cooperative’s Community Solar Program (Andalusia), Wiregrass Electric Cooperative (Hartford), and the forthcoming Little USA Community Solar Campus (Union Springs).", "sources": [{"url": "https://www.cnet.com/home/energy-and-utilities/which-states-have-community-solar-find-out-here/", "title": "Does Your State Have Community Solar? Find Out Here - CNET"}, {"url": "https://covington.coop/community-solar-garden/", "title": "Community Solar Garden – Covington Electric Cooperative"}, {"url": "https://www.wiregrass.coop/services/green-power-choice-community-solar-program/", "title": "Green Power Choice Community Solar Program – Wiregrass Electric Cooperative"}, {"url": "https://www.sweetgrownalabama.org/sga-members/1058", "title": "Little USA Community Solar Campus | Sweet Grown Alabama"}], "status": "none"},
  "Alaska": {"landscape": "The state has not explicitly defined or enabled community-owned solar, but community solar is codified, and SFA funds are available.", "policies": {"vnm": {"status": "No", "text": "Alaska has enabled net metering for organizations or individuals with a solar energy system on their property, and a recent bill was proposed to increase the benefits of this program. However, virtual net metering is not codified."}, "cs": {"status": "Yes", "text": "The 2024 Saving Alaskans Money with Voluntary Community Energy (SAVE) Act **(Senate Bill 152)** requires utilities to allow electricity providers to create community solar programs that may be owned by the utilities themselves or by “subscriber organizations.” Utilities may choose their own power capacity caps."}, "other": {"status": "Yes", "text": "The SAVE Act allows communities and nonprofits to serve as “subscriber organizations” that own or operate community solar facilities. Alaska was also granted $62 million by the federal government under the Solar For All (SFA) program. The Alaska Energy Authority, Alaska Housing Finance Corporation, and Tanana Chiefs Conference manage the state’s SFA funds, including the AKSFA Community Solar and Railbelt Tribal Community Solar programs, which are meant to benefit low-income and tribal residents, respectively. In addition, Alaska is a member of the Community Power Coalition, which collectively received $249 million in SFA funding."}}, "details": {"size": "Commercial subscribers must have a monthly demand of less than 50 kWh.", "eligibility": "Residential and commercial subscribers, as well as non-profit and for-profit subscription organizations, are all eligible, but must operate within a participating utility’s service area.", "benefitDist": "No specific benefit distribution is mandated."}, "activeCities": "Electric utilities have launched community solar farms in Anchorage and (forthcoming) Fairbanks. Additionally, two local tribes in Shungnak and Kobuk share ownership of a microgrid project. In an interview with the Clinic, the project leader stated that all tribal members automatically own shares and that subscribers hope to generate 25-30% of their electricity from solar by 2030.", "sources": [{"url": "https://ilsr.org/articles/alaskas-community-solar-program/", "title": "Alaska’s Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://www.solarpowerworldonline.com/2024/08/alaska-community-solar-law/", "title": "Alaska becomes the latest state to legalize community solar"}, {"url": "https://www.akenergyauthority.org/What-We-Do/Renewable-Energy-and-Energy-Efficiency/Solar/Solar-for-All", "title": "Solar for All"}, {"url": "https://www.adn.com/business-economy/energy/2024/08/13/alaska-gov-dunleavy-signs-measure-into-law-boosting-community-solar-projects/", "title": "Alaska Gov. Dunleavy signs measure into law boosting community solar projects - Anchorage Daily News"}, {"url": "https://alaskarenewableenergy.org/ppf/net-metering/", "title": "Net Metering: REAP"}, {"url": "https://programs.dsireusa.org/system/program/detail/3734", "title": "Net Metering"}, {"url": "https://environmentamerica.org/alaska/updates/annual-net-metering/", "title": "Annual Net Metering"}, {"url": "https://www.alaskaenergy.org/p/what-would-we-get-with-the-annual?utm_campaign=post&utm_medium=web", "title": "What would we get with the Annual Net Metering bill?"}, {"url": "https://akcenter.org/alaska-power-companies-look-at-building-community-solar-farms-that-households-can-invest-in/", "title": "Alaska power companies look at building community solar farms that households can invest in"}, {"url": "https://citizensenergy.com/five-organizations-turning-community-solar-into-savings-for-low-income-americans/", "title": "Five organizations turning community solar into savings for low-income Americans"}, {"url": "https://www.akenergytransparency.org/news/chugach-electric-launches-community-solar-project-others-soon-to-follow", "title": "Chugach Electric Launches Community Solar Project, Others May Follow Soon"}, {"url": "https://www.akleg.gov/PDF/33/Bills/SB0152Z.PDF", "title": "SB 152"}], "status": "active"},
  "American Samoa": {"landscape": "Although American Samoa has traditional net metering and substantial utility-scale solar, the territory does not have any policies around community or community-owned solar.", "policies": {"vnm": {"status": "No", "text": "American Samoa has only codified traditional net metering."}, "cs": {"status": "No", "text": "The territory has not codified community solar."}, "other": {"status": "No", "text": "There is no additional state support for community-owned solar."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "In 2022, the company Mana Solar received a $23.5 million grant from the U.S. Department of Agriculture to develop a 13.4-MW community solar and battery storage facility for 2,500 households on Tutuila Island. The power generated by this facility would be transmitted directly to the existing electric grid for distribution by the American Samoa Power Authority.", "sources": [{"url": "https://www.mvariety.com/news/regional_world/usda-invests-35-5m-in-american-samoa-solar-projects-to-deliver-affordable-clean-energy/article_12f7d886-c02b-11ef-b1bd-771082b6056d.html", "title": "USDA invests $35.5M in American Samoa solar projects to deliver affordable clean energy"}, {"url": "https://www.epa.gov/system/files/documents/2024-04/american-samoa-pcap.pdf", "title": "American Samoa | Priority Climate Action Plan"}, {"url": "https://www.eia.gov/state/analysis.php?sid=AQ", "title": "American Samoa - EIA"}, {"url": "https://www.rd.usda.gov/media/file/download/revised-ea-manasolar-061724-508.pdf", "title": "Draft Environmental Assessment - Mana Solar Project"}], "status": "none"},
  "Arizona": {"landscape": "Arizona does not have any policies explicitly enabling community-owned solar, but enables community solar more broadly.", "policies": {"vnm": {"status": "No", "text": "Arizona does not have any policies explicitly enabling virtual net metering."}, "cs": {"status": "Yes", "text": "In 2023, the Arizona Corporation Commission adopted a recommendation for a statewide community solar policy (Docket No. E-00000A-22-0103). Utilities may decline to participate in a community solar program and may terminate a community solar partnership at any time. Subscribers’ credits are equivalent to the utility’s avoided cost. Critics have characterized this recommendation as insufficient due to its “optional” nature for utilities and sub-retail rates, the lack of state financial support for developers, and the competitive RFP process for projects."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Arizona for a $156 million grant under the Solar for All program. The program focuses on increasing access to solar for low-income and disadvantaged communities by accelerating the deployment of rooftop solar, neighborhood solar projects, and solar-plus-storage systems. Arizona is also a member of the Community Power Coalition, which received $249 million under SFA, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "The recommendation does not include any size requirements for community solar projects.", "eligibility": "Both utilities and third parties can offer community solar, but the energy must come from a participating utility’s service area.", "benefitDist": "Projects must afford at least 50% of capacity to low- or moderate-income subscribers and 50% to nonprofits, educational institutions, municipalities, and small businesses."}, "activeCities": "Utilities in Tucson and Marana offer community solar options.", "sources": [{"url": "https://docket.images.azcc.gov/E000024471.pdf", "title": "Docket No. E-00000A-22-0103"}, {"url": "https://ilsr.org/articles/arizona-useless-community-solar-policy-2023/", "title": "Arizona Adopts a Useless Community Solar Policy - Institute for Local Self-Reliance"}, {"url": "https://www.azce.org/news/arizona-implements-a-controversial-and-ineffective-community-solar-policy", "title": "Arizona Implements a Controversial and Ineffective Community Solar Policy"}, {"url": "https://azcc.gov/substantive-policy-statement", "title": "Substantive Policy Statement"}, {"url": "https://www.solarreviews.com/blog/arizona-net-metering", "title": "What You Need To Know About Arizona’s Net Billing Program"}, {"url": "https://www.avviosolar.com/everything-you-need-to-know-about-net-metering/", "title": "Everything You Need To Know About Net Metering in Arizona - Avvio Solar"}, {"url": "https://www.aps.com/en/About/Sustainability-and-Innovation/Technology-and-Innovation/Solar-Communities", "title": "Solar Communities Program"}, {"url": "https://solarcollab.com/community-solar-energy-farm-program-in-arizona/", "title": "Community Solar Energy Farm Program In Arizona"}, {"url": "https://azgovernor.gov/office-arizona-governor/news/2024/04/arizona-wins-clean-energy-grant-expand-access-low-cost-energy", "title": "Arizona Wins Clean Energy Grant to Expand Access to Low-Cost Energy Options for Over 11,000 Arizonans"}, {"url": "https://www.tep.com/gosolartep/", "title": "GoSolar with TEP"}, {"url": "https://www.trico.coop/sustainable-energy/community-solar/", "title": "Community Solar - Trico Electric Coop"}], "status": "active"},
  "Arkansas": {"landscape": "Arkansas does not have any policies explicitly enabling community-owned solar.", "policies": {"vnm": {"status": "No", "text": "Arkansas allows net metering by facilities generating up to 1 MW, but this does not explicitly include remote net metering."}, "cs": {"status": "No", "text": "The state does not have any programs explicitly enabling community solar. In 2023, Arkansas had the seventh-most community solar megawatts installed of all states. A SEIA factsheet suggests that the vast majority of community solar projects were installed in 2018."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Arkansas for a $93 million grant under the Solar for All program. The program, under the nonprofit Hope Enterprise Corporation, will advance solar access and affordability for low-income and disadvantaged households. In addition, Arkansas is a member of the Clean Energy Fund of Texas and Southeast Rural Power Coalition, each of which received $156 million from SFA."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "SolarCollab, a private global platform for solar energy projects, offers a program for landowners in Augusta to lease their land for solar projects and own shares in the projects. The private SolarCollab program limits projects to 2-5 MW. Additionally, Microsoft has announced three large solar projects to serve 3,000 homes in rural counties across the state (Poinsett, Cross, and Desha).", "sources": [{"url": "https://www.arkleg.state.ar.us/Home/FTPDocument?path=%2FACTS%2F2023R%2FPublic%2FACT278.pdf", "title": "Act 278 of the Regular Session"}, {"url": "https://programs.dsireusa.org/system/program/detail/536", "title": "Net metering - DSIRE"}, {"url": "https://seia.org/state-solar-policy/arkansas-solar/", "title": "Arkansas – SEIA"}, {"url": "https://arkansasadvocate.com/2024/05/20/low-income-communities-priority-for-arkansas-93-6-million-federal-solar-grant/", "title": "Low-income communities are a priority for Arkansas’s $93.6 million federal solar grant"}, {"url": "https://www.cnet.com/home/solar/which-states-have-community-solar-find-out-here/", "title": "Does Your State Have Community Solar? Find Out Here"}, {"url": "https://solarcollab.com/community-owned-solar-farm-program-for-landowners-in-augusta-arkansas/", "title": "Community Solar Farms in Augusta, Arkansas,​ can now be owned by landowners and the local community."}, {"url": "https://www.uaex.uada.edu/environment-nature/energy/solar/net-metering.aspx", "title": "Net Metering Policies in Arkansas for Solar Energy"}, {"url": "https://www.entergy-arkansas.com/net-metering", "title": "Net metering – Entergy Arkansas"}, {"url": "https://pv-magazine-usa.com/2024/09/19/arkansas-to-cut-11-solar-net-metering-rate/", "title": "Arkansas to cut 1:1 solar net metering rate"}, {"url": "https://docs.nrel.gov/docs/fy23osti/84077.pdf", "title": "Status of State Community Solar Program Caps"}, {"url": "https://arktimes.com/arkansas-blog/2025/02/26/microsoft-backed-solar-projects-slated-for-rural-arkansas", "title": "Microsoft-backed solar projects slated for rural Arkansas"}, {"url": "https://www.landapp.com/post/solar-farm-leasing-in-arkansas", "title": "Solar Farm Leasing in Arkansas"}, {"url": "https://www.ecowatch.com/solar/incentives/ar", "title": "2025 Arkansas Solar Tax Credits, Rebates & Other Incentives"}], "status": "none"},
  "California": {"landscape": "California has enabled community-owned and community solar, as well as virtual net metering. The state has specific programs for low- and middle-income residents.", "policies": {"vnm": {"status": "Yes", "text": "California enables landlords to implement virtual net metering for solar systems on multi-tenant residential properties."}, "cs": {"status": "Yes", "text": "Income-qualified households may participate in a local community solar project if they have a “community sponsor” (Community Solar Green Tariff Program) or a grid-scale project otherwise (DAC Green Tariff). In either case, they receive a 20% discount. **(AB 327)** In early 2025, legislators introduced AB 1260, which would require at least 51% of each project to go to low-income subscribers. However, this bill is still in committee."}, "other": {"status": "Yes", "text": "The state explicitly enables community-owned solar through the Enhanced Community Renewables (ECR) program. This program is part of the Green Tariff Shared Renewables (GTSR) initiative and allows customers to purchase a share of a local renewable project. **(SB 43)** The state was also granted $250 million from the EPA under the Solar For All program and is a member of the $249 million Community Power Coalition. California is also one of the states prioritized by the Solar Access for National Affordable Housing Program, which SFA granted $250 million in total."}}, "details": {"size": "The Community Solar Green Tariff Program (for sponsored local projects) has a total cap of 41 MW, and the DAC Green Tariff (for grid-scale projects) has a total cap of 158 MW. GTSR, which includes the ECR program, has a total cap of 600 MW.", "eligibility": "Low-income households can participate in the CGST or the DAC Green Tariff. Anyone can participate in ECR.", "benefitDist": "100 MW of ECR is carved out for low-income communities."}, "activeCities": "Despite California’s first-in-the-nation rank in total solar capacity, community solar is a small part of its energy portfolio. The state says that over 23,000 customers currently participate in the DAC Green Tariff program. There do not appear to be any municipalities that have created their own community solar policies.", "sources": [{"url": "https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202120220AB2316", "title": "AB-2316 Public Utilities Commission: customer renewable energy subscription programs and the community renewable energy program"}, {"url": "http://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=PUC&sectionNum=2827.1", "title": "Assembly Bill (AB) 327"}, {"url": "https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=201320140SB43", "title": "SB 43"}, {"url": "https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/customer-generation/solar-in-disadvantaged-communities/the-community-solar-green-tariff-csgt-program", "title": "The Community Solar Green Tariff CSGT Program"}, {"url": "https://www.cpuc.ca.gov/-/media/cpuc-website/divisions/energy-division/documents/customer-generation/california_84092302_ggrf-sfa_workplan.pdf", "title": "The State of California’s Solar for All Program (CA-S4A)"}, {"url": "https://www.energy.ca.gov/programs-and-topics/programs/solar-all-program", "title": "Solar for All Program | California Energy Commission"}, {"url": "https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/customer-generation/state-of-california-solar-for-all-program", "title": "State of California Solar for All Program"}, {"url": "https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/community-solar-in-california", "title": "Community Solar in California"}, {"url": "https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/customer-generation/net-energy-metering-and-net-billing", "title": "Net Energy Metering and Net Billing"}, {"url": "https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/customer-generation/virtual-net-metering", "title": "Virtual Net Energy Metering"}, {"url": "https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/customer-generation/solar-in-disadvantaged-communities", "title": "Solar in Disadvantaged Communities"}, {"url": "https://legiscan.com/CA/text/AB1260/id/3223675/California-2025-AB1260-Amended.html", "title": "California-2025-AB1260-Amended"}, {"url": "https://envirovoters.org/archives/scorecard/2022/vote/ab-2316-a-8-30-22/", "title": "AB 2316 – Assembly Floor #2"}, {"url": "https://communitysolaraccess.org/news/legislation-to-expand-community-solar-storage-introduced-by-assemblymember-ward-in-california", "title": "Legislation to Expand Community Solar + Storage Introduced by Assemblymember Ward in California"}, {"url": "https://calmatters.org/environment/2024/05/california-community-solar-incentives/", "title": "California sides with big utilities, trimming incentives for community solar projects"}, {"url": "https://ilsr.org/articles/californias-community-solar-program/", "title": "California’s Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://www.greentechmedia.com/articles/read/inside-californias-community-solar-experiment", "title": "Inside California's Community Solar Experiment | Greentech Media"}, {"url": "https://seia.org/state-solar-policy/california-solar/", "title": "California – SEIA"}, {"url": "https://pv-magazine-usa.com/2025/03/04/california-community-solar-bill-offers-opportunity-to-reclaim-leadership/", "title": "California community solar bill offers opportunity to reclaim leadership – pv magazine USA"}, {"url": "https://pv-magazine-usa.com/2024/11/25/californias-new-community-solar-program-still-isnt-working/", "title": "California’s new community solar program still isn’t working – pv magazine USA"}, {"url": "https://www.energysage.com/local-data/community-solar/ca/", "title": "Community Solar in California | EnergySage"}, {"url": "https://www.canarymedia.com/articles/solar/california-regulators-torpedo-popular-plan-to-boost-community-solar", "title": "California regulators torpedo popular plan to boost community solar"}, {"url": "https://programs.dsireusa.org/system/program/detail/22429/enhanced-community-renewables-program", "title": "Enhanced Community Renewables Program"}, {"url": "https://programs.dsireusa.org/system/program/detail/276/net-metering-net-billing", "title": "Net Metering / Net Billing"}], "status": "active"},
  "Colorado": {"landscape": "Colorado has a strong community solar landscape that includes options for community ownership of facilities.", "policies": {"vnm": {"status": "Yes", "text": "Virtual/Remote Net Metering is enabled in **Senate Bill 21-261**. Customers who generate energy to be used in a “noncontiguous property” must receive off-site net metering credits from their utility’s net metering program. These credits might be lower than those under typical net metering, as the utility must bear additional costs associated with energy distribution. Colorado House Bill 23-1137 provides an alternative method for calculating the net metering credit utilities offer for the purchase of electricity output from a community solar garden. This provides stabilized and predictable energy savings through these credits. This bill was signed into law and became effective on August 7, 2023."}, "cs": {"status": "Yes", "text": "Legislation requires investor-owned electric utilities to provide inclusive community solar capacity. Utilities with more than 500,000 customers must provide at least 50 MW by February 1, 2026, and an additional 50 MW by February 1, 2027 (including unclaimed capacity from the previous cycle). Utilities with 500,000 or fewer customers must provide 3.5 MW by February 1, 2026, and an additional 3.5 MW by February 1, 2027.\nSubscribers receive bill credits proportional to their share of the facility’s output **(SB 24-207).**"}, "other": {"status": "Yes", "text": "Subscriber organizations (i.e., customers of a particular facility), as well as utilities, for-profits, and nonprofits, may own community solar gardens. In addition, Colorado received $156 million from the EPA’s Solar for All program, funded by the Inflation Reduction Act of 2022, to expand rooftop and community solar for income-qualified residents. Administered by the Colorado Energy Office, the Colorado Solar for All (COS4A) program will partner with industry leaders to develop and manage single-family, multifamily, and community solar projects. In addition, Colorado is a member of the Community Power Coalition, which was granted $249 million in total under SFA. The state is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program ($250 million total under SFA)."}}, "details": {"size": "Each new community solar facility must be ≤5 MW (alternating current) **(SB 24-207).**", "eligibility": "To qualify as community solar under Colorado SB 24-207, a project must:\n- Allocate at least 51% of capacity to income-qualified subscribers;\n- Allocate no more than 40% of capacity to a single subscriber;\n- Distribute no more than 120% of any customer’s expected annual electricity consumption (except income-qualified subscribers, who may receive up to 200%). **(SB 24-207)**", "benefitDist": "Subscribers receive bill credits based on their share of the facility’s output.\nIncome-qualified subscribers must receive a minimum discount on bill credits:\n- 25% for standard income-qualified participation.\n- 30% if the facility qualifies for IRA tax credits as an energy community project.\n- 50% if the facility qualifies for IRA tax credits specifically for income-qualified households. **(SB 24-207)**"}, "activeCities": "Colorado is one of the most advanced states for community-owned solar, with estimates that between 20 and 30 such projects generate over 15 MW of power annually.", "sources": [{"url": "https://leg.colorado.gov/bills/sb24-207?utm_source=chatgpt.com", "title": "https://leg.colorado.gov/bills/sb24-207"}, {"url": "https://leg.colorado.gov/sites/default/files/2021a_261_signed.pdf", "title": "SB 21-161"}, {"url": "https://leg.colorado.gov/sites/default/files/2019a_1003_signed.pdf", "title": "19-1003"}, {"url": "https://ilsr.org/article/energy-democracy/colorados-community-solar-program/", "title": "https://ilsr.org/article/energy-democracy/colorados-community-solar-program/"}], "status": "active"},
  "Commonwealth of the Northern Mariana Islands": {"landscape": "The Northern Mariana Islands does not have any community-owned solar policies.", "policies": {"vnm": {"status": "No", "text": "The territory requires its sole utility to offer traditional net metering, but virtual net metering does not appear to be offered."}, "cs": {"status": "No", "text": "NMI has no policies explicitly targeting community solar."}, "other": {"status": "No", "text": "The territory has not enabled community-owned solar through any policies."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "There do not appear to be any active community solar projects in NMI.", "sources": [{"url": "https://nationalcleanenergyweek.org/wp-content/uploads/2024/10/NCEW-2024-Proclamation-Northern-Mariana-Islands.pdf", "title": "NCEW Proclamation"}, {"url": "https://www.mvariety.com/news/local/cuc-board-looks-into-impact-of-solar-for-all-initiative-on-local-grid/article_00028032-ef2f-11ee-8209-8ff80826842e.html", "title": "CUC board looks into impact of ‘Solar for All’ initiative on local grid"}, {"url": "https://docs.nrel.gov/docs/fy24osti/88855.pdf", "title": "Energy Baseline Report"}, {"url": "https://programs.dsireusa.org/system/program/detail/5556/n-mariana-islands-net-metering", "title": "N. Mariana Islands - Net Metering | DSIRE"}], "status": "none"},
  "Connecticut": {"landscape": "Connecticut enables community and community-owned solar but has seen little development.", "policies": {"vnm": {"status": "Yes", "text": "Connecticut allows virtual net metering, albeit limited to state, agricultural, and municipal subscribers."}, "cs": {"status": "Yes", "text": "Connecticut has enabled community solar since the Shared Clean Energy Facility (SCEF) Program launched in 2015. This program allows participants to receive on-bill credits proportional to their average monthly electric usage."}, "other": {"status": "Yes", "text": "Under the SCEF, any non-utility entity, including the community itself, can own a community solar project. The state was awarded $62 million under the federal Solar For All program in 2024. In addition, Connecticut is a member of the Community Power Coalition, which was granted $249 million in total under SFA. The state is also one of those prioritized by the Solar Access for Nationwide Affordable Housing Program ($250 million total under SFA)."}}, "details": {"size": "The SCEF program allows projects ranging from 100 kW to 5 MW, with a cap of 50 MW per year for new installations.", "eligibility": "Projects must have at least ten subscribers to be eligible.", "benefitDist": "An information sheet states that SCEF credits are available for “low and moderate income residential customers, small businesses, low-income service organizations, and landlords of affordable housing facilities.” Utilities select 90% of subscribers automatically based on the eligibility criteria above, and any remaining participants must apply."}, "activeCities": "According to the Institute for Local Self-Reliance, the state has installed 6 MW of community solar capacity as of July 2025. In New Haven, one of the state’s most populous cities, the New Haven Community Solar program provides discounted electricity to a project focused on granting shelter to people without homes.", "sources": [{"url": "https://ilsr.org/articles/connecticuts-community-solar-program/", "title": "Connecticut's Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://programs.dsireusa.org/system/program/detail/22457/shared-clean-energy-facility-scef-program", "title": "Shared Clean Energy Facility (SCEF) Program"}, {"url": "https://pv-magazine-usa.com/2025/06/09/connecticut-house-passes-community-solar-bill-remains-dead-on-arrival-at-senate/", "title": "Connecticut House passes community solar bill, remains dead on arrival at the Senate"}, {"url": "https://portal.ct.gov/deep/energy/shared-clean-energy-facilities/shared-clean-energy-facilities", "title": "Shared Clean Energy Facilities"}, {"url": "https://www.solarreviews.com/blog/connecticut-net-metering-replacement-program", "title": "Overview Of Connecticut Net Metering (Residential Renewable Energy Solutions Program)"}, {"url": "https://www.cnet.com/home/solar/connecticut-solar-panel-incentives-tax-breaks-net-metering-and-more/", "title": "Connecticut Solar Panel Incentives: Tax Breaks, Net Metering and More - CNET"}, {"url": "https://portal.ct.gov/deep/energy/solar-for-all", "title": "Solar for All - Project SunBridge"}, {"url": "https://seia.org/state-solar-policy/connecticut-solar/", "title": "Connecticut – SEIA"}, {"url": "https://www.cga.ct.gov/2015/rpt/2015-r-0264.htm", "title": "VIRTUAL NET METERING"}, {"url": "https://programs.dsireusa.org/system/program/detail/22451", "title": "Non-Residential Renewable Energy Solutions Program"}, {"url": "https://www.uinet.com/documents/1678076/1703587/FINAL+URPC001+UI+SCEF+Fact+Sheet+Design+with+Spanish+10.18.24+%281%29.pdf/526bdbcc-a95d-973b-64db-a8ba944efe91?t=1735226276698", "title": "Shared Clean Energy Facility Program"}, {"url": "https://www.solarpowerworldonline.com/2024/05/verogy-completes-nearly-6-mw-community-solar-project/", "title": "Verogy completes nearly 6-MW community solar project in Connecticut"}, {"url": "https://newhavencommunitysolar.com/", "title": "New Haven Community Solar"}], "status": "active"},
  "Delaware": {"landscape": "Delaware enables community solar, including community-owned solar.", "policies": {"vnm": {"status": "No", "text": "Delaware does not appear to have legislation enabling virtual or remote net metering."}, "cs": {"status": "Yes", "text": "Delaware enables community solar through SB 267 (2010) and SB 2 (2021). These bills allow Delmarva Power customers to enroll in 1 to 4 community solar projects. Participants receive credits on their electricity bill at retail rates or wholesale energy supply rates, depending on whether they and the facility are on the same distribution facility."}, "other": {"status": "Yes", "text": "Delaware explicitly permits all non-utility entities, including communities, to own community solar projects. In addition, Delaware is a member of the Community Power Coalition and the Clean Energy Fund of Texas, which were granted $249 million and $156 million, respectively, under the federal Solar For All program. The state is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program ($250 million total under SFA)."}}, "details": {"size": "Community solar projects may be up to 4 MW.", "eligibility": "Subscribers can enroll in at most 110% of their expected energy consumption.", "benefitDist": "Every community solar project must allot at least 15% of subscriptions to low-income participants."}, "activeCities": "According to the Delaware Municipal Electric Corporation, a public electric utility, municipalities including Clayton, New Castle, and Smyrna have developed small community solar projects, but these are not community-owned.", "sources": [{"url": "https://ilsr.org/articles/delawares-community-solar-program/", "title": "Delaware’s Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://decommunitysolar.org/", "title": "Delaware Community Solar"}, {"url": "https://depsc.delaware.gov/community-energy-facilities/", "title": "Community Solar (Community Energy Facilities) - Delaware Public Service Commission (PSC) - State of Delaware"}, {"url": "https://programs.dsireusa.org/system/program/detail/22464/delaware-community-solar-rules", "title": "Delaware - Community Solar Rules"}, {"url": "https://solardelaware.org/im-interested-in/delaware-solar-policy/", "title": "Delaware Solar Policy"}, {"url": "https://programs.dsireusa.org/system/program/detail/43", "title": "Delaware, net metering"}, {"url": "https://irecusa.org/blog/irec/delaware-allows-community-net-metering-meter-aggregation/", "title": "Delaware Allows Community Net Metering, Meter Aggregation - Interstate Renewable Energy Council (IREC)"}, {"url": "https://seia.org/state-solar-policy/delaware-solar/", "title": "Delaware – SEIA"}, {"url": "https://pv-magazine-usa.com/2021/09/21/delaware-gov-signs-bill-easing-community-solar-access/", "title": "Delaware Gov. signs bill easing community solar access"}, {"url": "https://www.delmarva.com/smart-energy/my-green-power-connection/developers-contractors/community-solar-resources/community-solar-resources-de", "title": "Community Solar Resources (Delmarva)"}, {"url": "https://www.pivotenergy.net/blog/community-solar-markets-a-state-review-0", "title": "Community Solar Markets: A State Review"}, {"url": "https://www.delaware.coop/energy-savings-programs/co-op-community-solar", "title": "Co-op Community Solar | Delaware Electric Cooperative"}, {"url": "https://nautilussolar.com/news/powering-up-delaware-nautilus-solar-energy-and-turningpoint-energy-launch-one-of-the-first-solar-farms-in-major-renewable-energy-portfolio", "title": "Powering Up Delaware: Nautilus Solar Energy and TurningPoint Energy Launch One of the First Solar Farms in Major Renewable Energy Portfolio"}, {"url": "https://www.demecinc.net/generation/solar-energy/", "title": "Solar Energy - Delaware Municipal Electric Corporation"}, {"url": "https://legis.delaware.gov/BillDetail?LegislationId=142431", "title": "SB 175"}], "status": "active"},
  "District of Columbia": {"landscape": "DC enables community solar, including community-owned solar, but does not make specific allocations for low-income residents.", "policies": {"vnm": {"status": "Yes", "text": "Virtual net metering is enabled under B20-0057 for facilities with at least two subscribers. Credits are set to the full retail rate."}, "cs": {"status": "Yes", "text": "Community solar is available via Section 34 of the Code of the District of Columbia and the Community Renewable Energy Amendment Act."}, "other": {"status": "Yes", "text": "DC allows communities to own, install, and operate solar facilities. In addition, under the federal Solar For All (SFA) program, the district was granted $62 million to further solar development for low-income communities, with community ownership highlighted as a potential mechanism. DC is also a member of the Community Power Coalition and the Clean Energy Fund of Texas, which were awarded $249 million and $156 million in SFA grants, respectively."}}, "details": {"size": "Projects are limited to 5 MW each.", "eligibility": "Facilities must have at least two subscribers, and each subscriber may offset up to 120% of their annual consumption.", "benefitDist": "There are no specific carveouts for low- or moderate-income residents."}, "activeCities": "Community solar projects have been installed on residential buildings and churches to serve income-qualified residents.", "sources": [{"url": "https://code.dccouncil.gov/us/dc/council/code/sections/34-1518.01", "title": "Section 34–1518.01"}, {"url": "https://legiscan.com/DC/bill/B20-0057/2013", "title": "B20-0057"}, {"url": "https://solarunitedneighbors.org/resources/net-metering-in-dc/", "title": "https://solarunitedneighbors.org/resources/net-metering-in-dc/"}, {"url": "https://www.dcseu.com/impact-story/6-community-solar-sites-in-dc-you-didnt-know-were-helping-residents-save-money", "title": "https://www.dcseu.com/impact-story/6-community-solar-sites-in-dc-you-didnt-know-were-helping-residents-save-money"}, {"url": "https://doee.dc.gov/solarforall", "title": "https://doee.dc.gov/solarforall"}, {"url": "https://solarunitedneighbors.org/resources/community-solar-in-d-c-2/", "title": "https://solarunitedneighbors.org/resources/community-solar-in-d-c-2/"}, {"url": "https://www.pepco.com/smart-energy/my-green-power-connection/solar-for-home-business/community-solar/community-solar-dc", "title": "https://www.pepco.com/smart-energy/my-green-power-connection/solar-for-home-business/community-solar/community-solar-dc"}, {"url": "https://programs.dsireusa.org/system/program/detail/22455/community-renewable-energy-amendment-act", "title": "https://programs.dsireusa.org/system/program/detail/22455/community-renewable-energy-amendment-act"}, {"url": "https://doee.dc.gov/page/solar-all-community-solar-and-strategic-partnerships", "title": "https://doee.dc.gov/page/solar-all-community-solar-and-strategic-partnerships"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}], "status": "active"},
  "Florida": {"landscape": "Despite Florida’s lack of laws enabling community or community-owned solar, the state has the most community solar in the country.", "policies": {"vnm": {"status": "No", "text": "Florida does not have any laws explicitly enabling virtual or net metering."}, "cs": {"status": "No", "text": "The state has no laws explicitly enabling community solar. Despite the lack of legislation, Florida has the most community solar and the third most overall solar development of any state in the country. This is possibly because investor-owned utilities (FPL, Duke Energy, Tampa Electric, and Florida Public Utilities Corporation) all offer forms of community solar."}, "other": {"status": "No", "text": "Florida does not have any laws explicitly enabling community-owned solar. State law does not allow power purchase agreements (PPAs). In 2024, Florida was awarded $156 million from the federal government under the Solar For All program. In addition, the state is a member of the Community Power Coalition, the Clean Energy Fund of Texas, and the Southeast Rural Power Coalition, which were granted $249 million, $156 million, and $156 million in total, respectively. The state is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program ($250 million total under SFA)."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The Lake Worth Beach Electric Utility, a citizen-owned utility that serves around 28,000 customers, offers 13 MW of solar as part of its renewable energy subscription plan.", "sources": [{"url": "https://solarunitedneighbors.org/news/dont-be-fooled-by-fpls-fake-community-solar/", "title": "Florida Power & Light's (FPL) SolarTogether program is fake community solar"}, {"url": "https://www.fpl.com/energy-my-way/solar/solartogether-res.html", "title": "FPL | Energy My Way | SolarTogether | Residential"}, {"url": "https://www.cnet.com/home/solar/which-states-have-community-solar-find-out-here/", "title": "Does Your State Have Community Solar? Find Out Here"}, {"url": "https://www.solarreviews.com/blog/florida-net-metering-guide", "title": "Guide to Net Metering in Florida - 2025 Update"}, {"url": "https://environmentamerica.org/florida/articles/rooftop-solar-and-net-metering-in-florida/", "title": "Rooftop solar and net metering in Florida"}, {"url": "https://www.energysage.com/local-data/net-metering/fpl/", "title": "2025 Florida Power and Light (FPL) Net Metering | EnergySage"}, {"url": "https://www.solarsource.com/blog/why-does-florida-prohibit-ppas", "title": "Why Does Florida Prohibit PPAs?"}, {"url": "https://floridaspecifier.com/issues/volume-45-number-1/ppas-what-are-they-and-why-are-they-not-in-florida/", "title": "PPAs: What are they and why are they not in Florida? - Florida Specifier"}, {"url": "https://www.cnet.com/home/solar/does-your-state-allow-power-purchase-agreements-find-out-here/", "title": "Does Your State Allow Power Purchase Agreements? Find Out Here - CNET"}, {"url": "https://www.fpl.com/clean-energy/net-metering/guidelines.html", "title": "Net Metering Guidelines - Clean Energy"}, {"url": "https://programs.dsireusa.org/system/program/detail/2880", "title": "Net Metering"}, {"url": "https://seia.org/state-solar-policy/florida-solar/", "title": "Florida – SEIA"}, {"url": "https://docs.nrel.gov/docs/fy25osti/91361.pdf", "title": "Sharing the Sun: Community Solar Deployment and Subscriptions (as of June 2024)"}, {"url": "https://fmpa.com/solar/", "title": "Florida Municipal Solar Project"}, {"url": "https://www.psc.state.fl.us/library/filings/2020/01010-2020/01010-2020.pdf", "title": "PSC Statement against SolarTogether"}, {"url": "https://www.ouc.com/sustainability/solar-initiatives/", "title": "Solar Initiatives - Orlando Utilities Commission"}, {"url": "https://citizenownedenergy.com/", "title": "Citizen Owned Energy"}], "status": "limited"},
  "Georgia": {"landscape": "Georgia does not have any community or community-owned solar policies.", "policies": {"vnm": {"status": "No", "text": "The state allows net metering, including third-party-owned net metered systems, but does not describe any form of virtual or remote net metering."}, "cs": {"status": "No", "text": "Georgia does not have any policies explicitly enabling community solar. In 2025, state legislators introduced the Homegrown Solar Act, which would have allowed for community solar projects of up to 5 MW. This bill did not advance but will be revisited in the 2026 lawmaking session. However, in July 2025, Georgia Power, one of the state’s electric utilities, agreed to expand support for community solar."}, "other": {"status": "No", "text": "Georgia does not have any policies explicitly enabling community-owned solar. In 2024, the state earned a $156 million grant from the federal government under the Solar For All program, which is meant to support low-income residents, including via nonprofit- or utility-owned community solar. In addition, Georgia is a member of the Community Power Coalition, the Clean Energy Fund of Texas, and the Southeast Rural Power Coalition, which were granted $249 million, $156 million, and $156 million in total, respectively. The state is also one of those prioritized by the Solar Access for Nationwide Affordable Housing Program ($250 million total under SFA)."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Georgia ranks 7th in total solar capacity, but most of it is owned by utilities rather than community solar. Most of the state’s community solar capacity was built in 2017 or 2019. No cities appear to have instituted their own community solar policies.", "sources": [{"url": "https://environmentamerica.org/georgia/updates/georgia-homegrown-solar-act-introduced/", "title": "Georgia Homegrown Solar Act introduced"}, {"url": "https://programs.dsireusa.org/system/program/detail/574", "title": "Net Metering"}, {"url": "https://www.energysage.com/local-data/net-metering/georgia-power/", "title": "2025 Georgia Power Net Metering | EnergySage"}, {"url": "https://capitalgoodfund.org/bright/solar-for-all/", "title": "Solar For All: Georgia BRIGHT Communities Initiative"}, {"url": "https://seia.org/state-solar-policy/georgia-solar/", "title": "Georgia – SEIA"}, {"url": "https://www.residentialsolarpanels.org/community-and-social-impact/georgia-community-solar-power-your-home-without-installing-panels/", "title": "Georgia Community Solar: Power Your Home Without Installing Panels"}], "status": "none"},
  "Guam": {"landscape": "Guam has taken steps towards distributed energy resources, but some of its most impactful plans rely on federal resources", "policies": {"vnm": {"status": "No", "text": "In 2016, legislators introduced Bill 363-33, which would have enabled virtual net metering systems, but it did not pass. Bill 351, which passed in 2022, proposes creating a “virtual power plant,” capped at 20 MW total, of privately owned rooftop solar systems whose owners are paid for power fed back into the grid."}, "cs": {"status": "No", "text": "Guam does not appear to have enacted traditional community solar."}, "other": {"status": "No", "text": "Guam has not allocated any resources specifically for community-owned solar. The territory received a $62 million Solar For All (SFA) grant to support rooftop community solar projects, but the SFA program was shut down in August 2025."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "There do not appear to be any operating community solar projects in Guam.", "sources": [{"url": "https://web.archive.org/web/20250220054405/https://www.guamlegislature.com/Bills_Introduced_33rd/Bill%20No.%20B363-33%20(COR).pdf", "title": "Community Equal Access to Affordable Renewable Energy Act"}, {"url": "https://www.guamlegislature.com/36th_Guam_Legislature/Voting_Records_36th/ABill%20No.%20351-36%20(COR)%20PASSED.pdf", "title": "Virtual Power Plant program"}, {"url": "https://energy.guam.gov/sfaguam/", "title": "Solar for All | GEO"}, {"url": "https://archives.guamlegislature.gov/bills-history/", "title": "Guam Legislature Bill History"}, {"url": "https://www.guampdn.com/news/local/bill-could-give-non-solar-panel-users-a-taste-of-renewable-energy/article_d3aa99b1-ef1b-5c64-9b43-3c31a43d67c3.html", "title": "Bill could give non-solar panel users a taste of renewable energy"}, {"url": "https://www.postguam.com/news/local/bill-would-remove-solar-power-cap/article_0949aece-62bd-11e6-aac0-4f59134d8327.html", "title": "Bill would remove solar power cap"}, {"url": "https://www.postguam.com/news/local/renewable-energy-bill-gets-mixed-reaction/article_9ed4f4fa-849e-11e6-a16c-4379f3c42c4e.html", "title": "Renewable energy bill gets mixed reaction"}, {"url": "https://www.guampdn.com/news/ridgell-turn-sun-baked-rooftops-into-virtual-power-plant/article_13aaeebc-66fa-11ed-8108-936ce656ea5e.html", "title": "Ridgell: Turn sun-baked rooftops into 'virtual power plant'"}, {"url": "https://www.guampdn.com/news/parkinson-backs-low-income-community-solar-gardens-grid-resilience-projects/article_56fcf9cc-ed58-11ee-8846-bf5e165074cc.html", "title": "Parkinson backs low-income community solar gardens, grid resilience projects"}, {"url": "https://www.postguam.com/news/local/solar-for-all-program-aims-to-bring-renewable-energy-to-low-income-households/article_42beca7b-0c05-453f-b70a-f8b08d1270eb.html", "title": "Solar For All program aims to bring renewable energy to low-income households"}], "status": "limited"},
  "Hawaii": {"landscape": "Hawaii has made strides towards community solar, but has not developed many projects.", "policies": {"vnm": {"status": "No", "text": "Hawaii does not appear to currently have any form of net metering, virtual or otherwise."}, "cs": {"status": "Yes", "text": "The state has enabled some form of community solar, which the state calls Community-Based Renewable Energy, since 2015. Developers are responsible for finding subscribers who earn credits applied to their electricity bills. Credits expire after 12 months. **Senate Bill 589**, enacted in July 2025, mandates the state’s Public Utilities Commission to establish specific tariffs and rules for grid services, microgrids, and community-based renewable energy. The bill is intended to untangle regulatory roadblocks and complexity to improve the financial viability of shared solar farms."}, "other": {"status": "Yes", "text": "Hawaii explicitly allows groups like neighborhoods or churches to operate community solar projects. Hawaii was afforded $62 million under the federal Solar For All program in 2024 and is a member of the Community Power Coalition, which was granted $249 million in total."}}, "details": {"size": "Community solar projects must be at least 25 kW and have at least four subscribers, none of whom have more than 40% of the capacity. Projects of less than 250 kW are granted streamlined review. 30 MW of the overall 250 MW cap for the current phase of the project is allotted to sub-250 kW projects only.", "eligibility": "At least 40% of every project must go to residential customers. Subscribers may not subscribe to both a community solar and a net metering program.", "benefitDist": "One project on each of the islands of Oahu, Hawaii Island, and Maui must serve only low- and moderate-income households."}, "activeCities": "The state hopes to have 200 MW of community solar by 2030. The residents of Kauai have access to Kauai Island Electric Cooperative, a community-owned utility, which generates 50% of its energy from renewable sources. The cooperative has granted funds to utilities to develop large-scale solar and battery storage projects, but customers still own these and other parts of the grid. Similarly, the Ho’āhu Energy Cooperative on Molokai is a member-owned organization. Members participate in workshops to make consensus-based decisions for community solar and nanogrid projects, including a 250 kWac and a 2.2 MWac solar project, each paired with battery storage.", "sources": [{"url": "https://ilsr.org/articles/hawaiis-community-solar-program/", "title": "Hawaii’s Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://seia.org/state-solar-policy/hawaii-solar/", "title": "Hawai'i – SEIA"}, {"url": "https://www.hawaiianelectric.com/products-and-services/smart-renewable-energy-programs/shared-solar", "title": "Shared Solar | Hawaiian Electric"}, {"url": "https://energy.hawaii.gov/community-based-renewable-energy/", "title": "Renewable Energy - Hawai‘i State Energy Office"}, {"url": "https://www.hawaiianelectric.com/clean-energy-hawaii/selling-power-to-the-utility/competitive-bidding-for-system-resources/community-based-renewable-energy-(cbre)-for-low-and-moderate-income-(lmi)-rfps", "title": "Community-Based Renewable Energy (CBRE) for Low-and Moderate-Income (LMI) RFPs"}, {"url": "https://www.altuspower.com/states/hawaii", "title": "Community Solar in Hawaii: Sign Up and Save | Altus Power"}, {"url": "https://www.civilbeat.org/2025/06/community-solar-farms-to-save-money-fail-to-gain-traction-in-hawaii/", "title": "Community Solar Farms Meant To Save Money Fail To Gain Traction In Hawaiʻi"}, {"url": "https://www.renewableenergyworld.com/solar/community-solar/hawaiis-largest-community-solar-project-nears-completion/", "title": "Hawaii's largest community solar project nears completion"}, {"url": "https://programs.dsireusa.org/system/program/detail/22458/community-renewable-energy-program", "title": "Community Renewable Energy Program"}, {"url": "https://haleakalasolar.com/why-did-hawaii-stop-net-metering/", "title": "Why Did Hawaii Stop Net Metering? - Haleakala Solar"}, {"url": "https://www.utilitydive.com/news/hawaiian-electric-incentives-rooftop-solar-net-metering-battery-energy-storage/712215/", "title": "Hawaiian Electric offers new incentives to customers with rooftop solar and battery storage | Utility Dive"}, {"url": "https://programs.dsireusa.org/system/program/detail/596", "title": "Smart Renewable Energy Tariffs"}, {"url": "https://grist.org/climate-energy/how-changes-to-hawai%CA%BBis-home-battery-program-could-hinder-its-clean-energy-transition/", "title": "How changes to Hawaiʻi's home battery program could hinder its clean energy transition"}, {"url": "https://www.canarymedia.com/articles/energy-storage/hawaii-used-rooftop-solar-to-shore-up-the-grid-new-rules-threaten-that", "title": "Hawaii used rooftop solar to shore up the grid. New rules threaten…"}, {"url": "http://www.ililani.media/2025/06/puc-anticipates-explosive-growth-in.html", "title": "Ililani Media: PUC Anticipates Explosive Growth in Shared Solar"}, {"url": "https://cca.hawaii.gov/dca/community-based-renewable-energy/", "title": "Consumer Advocacy – Public Utilities (DCA) | Community-Based Renewable Energy (CBRE)"}, {"url": "https://www.hawaiianelectric.com/products-and-services/smart-renewable-energy-programs/previous-renewable-programs/net-energy-metering-plus", "title": "Net Energy Metering Plus | Hawaiian Electric"}, {"url": "https://www.hawaiianelectric.com/products-and-services/smart-renewable-energy-programs/previous-renewable-programs/net-energy-metering", "title": "Net Energy Metering | Hawaiian Electric"}, {"url": "https://hoahuenergy.coop/", "title": "Hoʻāhu Energy Cooperative Molokai"}, {"url": "https://ilsr.org/articles/ho%CA%BBahu-energy-cooperative-ler230/", "title": "On Molokai, A Community Cooperative for Energy Sovereignty | ILSR"}, {"url": "https://www.utilitydive.com/news/hawaii-kiuc-puc-solar-plus-storage-aes/742965/", "title": "Hawaiian utility contracts for solar-plus-storage projects from AES"}, {"url": "https://kiuc.coop/", "title": "Kauaʻi Island Utility Cooperative"}, {"url": "https://www.canarymedia.com/articles/clean-energy/kauai-is-a-clean-energy-leader-its-secret-a-publicly-owned-grid", "title": "Kauai became a clean energy leader. Its secret? A publicly owned grid"}, {"url": "https://www.capitol.hawaii.gov/session2015/bills/GM1200_.PDF", "title": "https://www.capitol.hawaii.gov/session2015/bills/GM1200_.PDF"}, {"url": "https://hpuc.my.site.com/cdms/s/search?term=PUC%20Docket%20No.%202015-0389&excludeObjects", "title": "PUC Docket No. 2015-0389"}, {"url": "https://www.hawaiianelectric.com/documents/products_and_services/customer_renewable_programs/PUC_order_37070_commencing_ph2_of_cbre_program.pdf", "title": "PUC Order 37070"}], "status": "active"},
  "Idaho": {"landscape": "The state has not enabled community-owned solar through any policies.", "policies": {"vnm": {"status": "No", "text": "Idaho does not have a net metering policy, including virtual net metering. Instead, the state’s three utilities have created their own net-billing tariffs. Net-billed systems are limited to 25 kW for residential or small commercial customers and 100 kW for other customers."}, "cs": {"status": "No", "text": "Idaho has no policies explicitly targeting community solar."}, "other": {"status": "No", "text": "Idaho does not have any policies targeting community-owned solar. However, Idaho has received $54 million under the federal government’s Solar For All program and is part of the Community Power Coalition, which was awarded a $249 million grant of its own. Idaho is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received a $250 million SFA grant."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "A fact sheet from SEIA suggests that communities across the state installed very few community solar facilities. The first project in the state was built in Sagle in 2017 and generates 50 kW of power.", "sources": [{"url": "https://seia.org/state-solar-policy/idaho-solar/", "title": "Idaho – SEIA"}, {"url": "https://www.sierraclub.org/idaho/community-solar", "title": "Community Solar | Sierra Club"}, {"url": "https://www.solarpowerworldonline.com/2024/01/idaho-ends-net-metering-shifts-instead-to-net-billing-system-for-solar-compensation/#:~:text=for%20solar%20compensation-,Idaho%20ends%20net%20metering%2C%20shifts%20instead%20to%20net,billing%20system%20for%20solar%20compensation&text=The%20Idaho%20Public%20Utilities%20Commission,basis%20for%20solar%20system%20owners", "title": "Idaho ends net metering, shifts instead to net-billing system for solar compensation"}, {"url": "https://programs.dsireusa.org/system/program/detail/279/idaho-power-net-metering", "title": "Idaho Power - Net Metering"}, {"url": "https://www.nli.coop/programs-and-services/community-solar/about/", "title": "About Community Solar - Northern Lights"}], "status": "none"},
  "Illinois": {"landscape": "Illinois’ community solar policies incentivize community ownership of facilities and involvement in their development.", "policies": {"vnm": {"status": "Yes", "text": "Utilities must offer virtual net metering/meter aggregation for facilities that generate up to 5 MW."}, "cs": {"status": "Yes", "text": "Illinois has two main programs advancing community solar use: Illinois Shines and Illinois Solar For All (ILSFA). Both ILSFA and Illinois Shines were created in 2016’s Future Energy Jobs Act (FEJA, SB 2814) and expanded in 2021’s Climate and Equitable Jobs Act (CEJA, Public Act 102-0662) Illinois Shines allows both community-driven and traditional community solar across income levels, while ILSFA focuses on utility-owned community solar subscriptions for income-qualified residents. Both programs give participants credits on their electricity bills proportional to the share of electricity generated. Bill credit rates may vary by utility."}, "other": {"status": "Yes", "text": "Illinois Shines allows communities to participate in Community-Driven Solar (CDS) projects. The state allocates resources to build these projects based on selection criteria that include the percentage of community ownership, additional community benefits, and community involvement during development. In addition, Illinois has received $156 million under the federal government’s Solar For All program. It is part of the Community Power Coalition, which was awarded a $249 million grant of its own. Illinois is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received a $250 million SFA grant."}}, "details": {"size": "Community solar projects can be up to 5 MW.", "eligibility": "5% of the Illinois Shines program is carved out for community-driven solar projects.", "benefitDist": "To participate in ILSFA, a household must be below 80% of the area median income. 25% of ILSFA’s budget is reserved for environmental justice communities."}, "activeCities": "Per the Institute for Local Self-Reliance, as of 2025, Illinois has 393 MWac of community solar operating statewide, including several operated by municipalities or cooperatives.", "sources": [{"url": "https://www.ilga.gov/legislation/publicacts/99/PDF/099-0906.pdf", "title": "Future Energy Jobs Act"}, {"url": "https://www.ilga.gov/documents/legislation/publicacts/102/PDF/102-0662.pdf", "title": "Climate and Equitable Jobs Act"}, {"url": "https://ilsr.org/articles/illinois-community-solar-program/", "title": "Illinois's Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://illinoisshines.com/exploring-community-solar/", "title": "Exploring Community Solar – Illinois Shines"}, {"url": "https://www.illinoissfa.com/community-solar/", "title": "Community Solar"}, {"url": "https://www.citizensutilityboard.org/community-solar-illinois/", "title": "Community Solar in Illinois | Citizens Utility Board"}, {"url": "https://ipa.illinois.gov/content/dam/soi/en/web/ipa/documents/power-hour/unpacking-community-solar-within-ilfsa-72723-final.pdf", "title": "Unpacking Community Solar Within Illinois Solar for All"}, {"url": "https://www.citizensutilityboard.org/illinois-net-metering/", "title": "Illinois Net Metering | Citizens Utility Board"}, {"url": "https://illinoisshines.com/wp-content/uploads/2024/07/FAQs-Related-to-Changes-in-Net-Metering-In-Illinois-AVs-and-Designees-26July2024-1.pdf", "title": "FAQs Related to Changes in Net Metering in Illinois: AV- and Designee-Facing"}, {"url": "https://seia.org/state-solar-policy/illinois-solar/", "title": "Illinois – SEIA"}, {"url": "https://ipa.illinois.gov/content/dam/soi/en/web/ipa/documents/10-20-22-ipa-il-shines-factsheet.pdf", "title": "Illinois Shines"}, {"url": "https://illinoisshines.com/community-driven-community-solar/", "title": "Community-Driven Community Solar – Illinois Shines"}, {"url": "https://ilsr.org/articles/community-solar-tracker/", "title": "Community Solar Tracker - ILSR Energy Democracy Initiative"}, {"url": "https://programs.dsireusa.org/system/program/detail/2700/net-metering", "title": "Illinois net metering"}, {"url": "https://programs.dsireusa.org/system/program/detail/22442/illinois-solar-for-all-program", "title": "Illinois Solar for All Program"}, {"url": "https://programs.dsireusa.org/system/program/detail/22441/adjustable-block-program-illinois-shines", "title": "Adjustable Block Program (Illinois Shines)"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "Solar for All | US EPA"}, {"url": "https://programs.dsireusa.org/system/program/detail/2700", "title": "Illinois Net Metering | DSIRE"}, {"url": "https://illinoiscommunitysolarauthority.com/illinois-community-success-stories/", "title": "Illinois Community Success Stories"}, {"url": "https://www.canarymedia.com/articles/enn/illinois-muni-and-co-op-members-want-in-on-states-solar-boom", "title": "Illinois muni and co-op members want in on state’s solar boom"}, {"url": "https://gejc.org/solar-in-illinois/", "title": "Community-Owned Solar in Illinois - Green Energy Justice Cooperative"}, {"url": "https://illinoisshines.com/project-map/", "title": "Project Map - Illinois Shines"}], "status": "active"},
  "Indiana": {"landscape": "Indiana does not have any policies enabling community-owned solar or virtual net metering.", "policies": {"vnm": {"status": "No", "text": "Indiana does not appear to have a virtual net metering program. Overall, Indiana’s net metering landscape has become more limited for consumers in recent years. The state aims to phase out net metering entirely by 2047. In 2022, Indiana reduced net metering benefits from their previous level (retail rates)."}, "cs": {"status": "No", "text": "Although an SEIA study ranked Indiana 15th in the nation in total solar capacity, it also suggested that community solar accounted for a marginal share of the state's portfolio. In early 2025, lawmakers in the Indiana state legislature introduced two bills to enable community solar. However, neither bill advanced."}, "other": {"status": "No", "text": "Indiana does not have any policies explicitly enabling community-owned solar. However, the state was awarded $117 million by the federal government under the Solar For All program in 2024. In addition, Indiana is part of the multi-state Industrial Heartland Solar Coalition and the Community Power Coalition, which received $156 million and $249 million in additional SFA funding, respectively."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Indianapolis, the largest city in the state, is developing a community solar project that could generate up to 12 MW of power. Other municipalities, including Fort Wayne and Columbus, also appear to be developing community solar projects.", "sources": [{"url": "https://www.epa.gov/newsreleases/biden-harris-administration-announces-indiana-community-action-association-receive", "title": "Biden-Harris Administration Announces Indiana Community Action Association to Receive More Than $117 Million to Deliver Residential Solar, Lowering Energy Costs and Advancing Environmental Justice Across Indiana"}, {"url": "https://insfa.org/", "title": "Indiana Solar for All"}, {"url": "https://solarunitedneighbors.org/resources/net-metering-in-indiana/", "title": "Net metering in Indiana - Solar United Neighbors"}, {"url": "https://www.canarymedia.com/articles/enn/in-indiana-solar-net-metering-rules-go-from-bad-to-worse", "title": "In Indiana, solar net metering rules go from bad to worse"}, {"url": "https://programs.dsireusa.org/system/program/detail/342", "title": "Net Metering"}, {"url": "https://www.in.gov/iurc/news-and-notices/newsroom/2017-technical-conference-addressing-questions-re-implementation-of-net-metering-legislation-sea-309/net-metering-resource-page/", "title": "Net Metering Resource Page - IURC"}, {"url": "https://pv-magazine-usa.com/2023/11/21/indiana-killed-net-metering-solar-down-67-utility-now-seeking-23-rate-increase/", "title": "Indiana killed net metering, solar down 67%, utility now seeking 23% rate increase"}, {"url": "https://seia.org/state-solar-policy/indiana-solar/", "title": "Indiana – SEIA"}, {"url": "https://indianacapitalchronicle.com/briefs/mccormick-calls-for-net-metering-return-in-utility-plan/", "title": "McCormick calls for net metering return in utility plan • Indiana Capital Chronicle"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "Solar for All | US EPA"}, {"url": "https://indianacv.org/independent-community-solar-in-indiana-a-statewide-solution-that-promotes-energy-freedom-could-lower-energy-costs/", "title": "Independent Community Solar in Indiana"}, {"url": "https://mirrorindy.org/once-a-landfill-in-indy-soon-home-to-community-solar/", "title": "A landfill in Indy will soon be home to community solar"}, {"url": "https://www.yept.org/latest-stories/everything-youve-wanted-to-know-about-community-solar", "title": "Everything You’ve Always Wanted to Know about Community Solar"}], "status": "none"},
  "Iowa": {"landscape": "Iowa does not have any policies enabling community-owned solar, virtual net metering, or community solar.", "policies": {"vnm": {"status": "No", "text": "Although Iowa allows net metering with a net-billing or inflow-outflow model, the state appears to limit net metering capacity to on-site generation."}, "cs": {"status": "No", "text": "Although Iowa’s state legislature saw significant momentum towards community solar during the first half of 2025, neither of the bills that would have implemented the policy advanced."}, "other": {"status": "No", "text": "Iowa does not have any policies explicitly promoting community-owned solar. The state’s Solar For All proposal was rejected by the federal government in 2024. However, Iowa is a member of the Community Power Coalition, which received $249 million under SFA, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Several utility-owned community solar programs have sprung up across the state. The Farmer Electric Cooperative in Greenfield, which offers community solar options, may have the highest profile and was deemed the “#1 Solar Utility” by the Institute for Local Self-Reliance for its ambitious renewable energy goals.", "sources": [{"url": "https://www.iaenvironment.org/newsroom/energy-news/iec-laments-rejection-of-states-solar-for-all-proposal-", "title": "IEC laments rejection of state's Solar for All proposal - Iowa Environmental Council"}, {"url": "https://www.bleedingheartland.com/2024/05/06/iowa-loses-out-on-major-federal-grant-for-residential-solar/", "title": "Iowa loses out on major federal grant for residential solar - Bleeding Heartland"}, {"url": "https://communitysolaraccess.org/news/community-solar-passes-unanimously-out-of-iowa-house-commerce-committee", "title": "Community Solar Passes Unanimously Out of Iowa House Commerce Committee"}, {"url": "https://www.canarymedia.com/articles/solar/community-republican-support-states", "title": "Community solar is winning over Republican lawmakers… | Canary Media"}, {"url": "https://www.legis.iowa.gov/legislation/BillBook?ba=HSB81&ga=91", "title": "HSB 81"}, {"url": "https://seia.org/state-solar-policy/iowa-solar/", "title": "Iowa – SEIA"}, {"url": "https://programs.dsireusa.org/system/program/detail/488", "title": "Iowa's net-metering"}, {"url": "https://iuc.iowa.gov/regulated-industries/electric/site-distributed-generation", "title": "On-site (Distributed) Generation | Iowa Utilities Commission"}, {"url": "https://www.legis.iowa.gov/legislation/BillBook?ba=SF%20583&ga=88", "title": "Senate File 583"}, {"url": "https://iuc.iowa.gov/media/140/download?inline", "title": "Consumer Guide for On-Site Generation"}, {"url": "https://www.youtube.com/watch?v=mAX0FJkd5e8", "title": "The #1 Solar Utility is in…Iowa? - ILSR"}, {"url": "https://farmersrec.com/", "title": "Farmers Electric Cooperative"}, {"url": "https://www.alliantenergy.com/ways-to-save/community-solar", "title": "Alliant Energy® Community Solar"}, {"url": "https://www.midlandpower.coop/energy-efficiency/renewables/community-solar/", "title": "Community Power - Midland Power"}, {"url": "https://www.heartlandpower.com/community-solar", "title": "Community Solar - Heartland Power"}, {"url": "https://www.prairieenergy.coop/community-solar", "title": "Prairie Energy - Community Solar"}, {"url": "https://www.cleanenergydistricts.org/iowa-policy/2025-iowa-legislative-session", "title": "https://www.cleanenergydistricts.org/iowa-policy/2025-iowa-legislative-session"}], "status": "none"},
  "Kansas": {"landscape": "Kansas does not have any policies enabling community-owned solar.", "policies": {"vnm": {"status": "No", "text": "Kansas allows limited net metering for residential, non-residential, and educational customers. However, the state does not appear to have any policies enabling virtual net metering."}, "cs": {"status": "No", "text": "Kansas does not have any policies explicitly enabling community-owned or community solar."}, "other": {"status": "No", "text": "Kansas did not receive an individual federal Solar For All (SFA) grant. However, it is part of the Community Power Coalition and Industrial Heartland Solar Coalition, which received $249 million and $156 million in total, respectively, from SFA."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Several privately owned cooperatives across the state offer community solar options. However, development has been limited: Kansas is ranked last in the nation for solar capacity by SEIA, which found marginal community solar development.", "sources": [{"url": "https://www.kcc.ks.gov/electric/net-metering-in-kansas", "title": "Net Metering in Kansas"}, {"url": "https://programs.dsireusa.org/system/program/detail/3403", "title": "Net Metering"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "Solar for All | US EPA"}, {"url": "https://www.mwenergy.com/environmental/renewable-energy/community-solar", "title": "Community Solar | Midwest Energy"}, {"url": "https://www.bpu.com/ResourcesServices/SolarFarm.aspx", "title": "BPU Community Solar Farm"}, {"url": "https://seia.org/state-solar-policy/kansas-solar/", "title": "Kansas - SEIA"}, {"url": "https://pioneerelectric.coop/my-co-op/community-solar/", "title": "Community Solar - Pioneer Electric"}, {"url": "https://victoryelectric.net/community-solar", "title": "Community Solar | Victory Electric Cooperative"}, {"url": "https://www.weci.net/community-solar", "title": "Community Solar - Wheatland Electric Cooperative"}], "status": "none"},
  "Kentucky": {"landscape": "Kentucky does not have any policies that allow or explicitly prohibit community-owned solar.", "policies": {"vnm": {"status": "No", "text": "Kentucky allows net metering at rates set by its Public Service Commission (PSC); projects are capped at 45 kW. However, net metering is only allowed for systems existing on the customer-generator’s physical premises."}, "cs": {"status": "No", "text": "Kentucky does not have any programs explicitly enabling community solar."}, "other": {"status": "No", "text": "Kentucky does not have any programs enabling community-owned solar. However, the state received $62 million under the federal government’s Solar For All program in 2024. This funding appears to be targeted towards rooftop or individual installations. In addition, Kentucky is a member of the Clean Energy Fund of Texas, which received a total of $156 million of SFA funding."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The Solar Share program, organized by LGE & KU (a Louisville/Kentucky utility), allows individuals and businesses to subscribe to solar power.", "sources": [{"url": "https://eec.ky.gov/Energy/Programs/Documents/Solar%20for%20All%20FAQ.pdf", "title": "Solar for All FAQs"}, {"url": "https://kentuckylantern.com/briefs/kentucky-to-receive-62-million-to-expand-solar-energy-access-to-low-income-households/", "title": "Kentucky to receive $62 million to expand solar energy access to low-income households"}, {"url": "https://www.epa.gov/newsreleases/biden-harris-administration-announces-kentucky-receive-62450000-deliver-residential", "title": "Biden-Harris Administration Announces Kentucky to Receive $62,450,000 to Deliver Residential Solar, Lowering Energy Costs and Advancing Environmental Justice Across Kentucky | US EPA"}, {"url": "https://seia.org/state-solar-policy/kentucky-solar/", "title": "Kentucky – SEIA"}, {"url": "https://programs.dsireusa.org/system/program/detail/1081", "title": "Net metering programs"}, {"url": "https://psc.ky.gov/agencies/psc/Industry/Electric/Final%20Net%20Metering-Interconnection%20Guidelines%201-8-09.pdf", "title": "Interconnection and Net Metering Guidelines - Kentucky"}, {"url": "https://www.solarreviews.com/news/kentucky-net-metering-changes-to-affect-solar-customers", "title": "What Do Changes to Kentucky’s Net Metering Law Mean for Solar Customers?"}, {"url": "https://www.altuspower.com/post/is-community-solar-available-in-my-state", "title": "Is Community Solar Available in My State?"}, {"url": "https://apps.legislature.ky.gov/recorddocuments/bill/19RS/sb100/bill.pdf", "title": "AN ACT relating to net metering. 1 Be it enacted by the General Assembly of the Commonwealth of Kentucky: 2 *Section 1. KRS 27"}, {"url": "https://eec.ky.gov/Energy/Documents/Consumer%20Energy%20Management%20and%20Access%20Guide.pdf", "title": "Consumer energy Management & access guide"}, {"url": "https://lge-ku.com/solar-share/dashboard", "title": "Solar Share live dashboard | LG&E and KU"}, {"url": "https://www.solaralliance.com/utility-community-solar/", "title": "Community Solar Systems & Panels"}, {"url": "https://www.kyses.org/Solarize", "title": "Solarize - The Kentucky Solar Energy Society"}], "status": "none"},
  "Louisiana": {"landscape": "Louisiana does not have any policies explicitly targeting community-owned solar.", "policies": {"vnm": {"status": "No", "text": "Louisiana mandates that utilities allow net metering for residential, commercial, and agricultural customers. Participants are billed at the avoided cost rate. However, the most recent rules by the Public Service Commission (Docket R-33929) do not appear to mention virtual net metering."}, "cs": {"status": "No", "text": "Louisiana’s community solar laws appear to be limited to net metering, and the state has zero community solar projects, per SEIA and CNET."}, "other": {"status": "No", "text": "Although the state has not implemented any form of support for community-owned solar, Louisiana received $156 million in federal Solar For All funding. Beneficiaries will include rooftop solar installations on multifamily homes. In addition, Louisiana is a member of the Community Power Coalition and the Clean Energy Fund of Texas, which received $249 million and $156 million, respectively."}}, "details": {"size": "Net metered systems are capped at 300 kW.", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The New Orleans City Council has created a community solar program at retail rates, with 30% of any project under 5 MW carved out for low-income participants.", "sources": [{"url": "https://lpscpubvalence.lpsc.louisiana.gov/portal/PSC/DocketDetails?docketId=257", "title": "Link"}, {"url": "https://programs.dsireusa.org/system/program/detail/22465/louisiana-community-solar-net-metering-and-distributed-generation", "title": "Louisiana Community Solar Rules - DSIRE"}, {"url": "https://programs.dsireusa.org/system/program/detail/983", "title": "Louisiana Net Metering - DSIRE"}, {"url": "https://www.dnr.louisiana.gov/news/louisiana-denr-granted-156-million-in-federal-solar-funding", "title": "Louisiana DENR Granted $156 Million in Federal Solar Funding | Department of Energy and Natural Resources"}, {"url": "https://lailluminator.com/2025/03/18/solar-for-yall-faces-hazy-future-in-louisiana/", "title": "‘Solar for Y’all’ faces hazy future in Louisiana"}, {"url": "https://www.lpsc.louisiana.gov/Utilities_NetMetering", "title": "LPSC - Utilities Net Metering"}, {"url": "https://www.solarreviews.com/news/the-war-on-louisianas-net-metering", "title": "Changes to Louisiana's Net Metering: Why You Should Care"}, {"url": "https://www.entergylouisiana.com/net-metering", "title": "Net metering and distributed generation – Entergy Louisiana"}, {"url": "https://www.dnr.louisiana.gov/page/1789", "title": "Solar for Y'all | Department of Energy and Natural Resources | State of Louisiana"}, {"url": "https://www.cnet.com/home/solar/which-states-have-community-solar-find-out-here/", "title": "Does Your State Have Community Solar? Find Out Here"}, {"url": "https://www.entergyneworleans.com/community-solar", "title": "New Orleans City Council Community Solar Program"}, {"url": "https://seia.org/state-solar-policy/louisiana-solar/", "title": "Louisiana - SEIA"}, {"url": "https://programs.dsireusa.org/system/program/detail/22487/city-of-new-orleans-community-solar-rules", "title": "City of New Orleans - Community Solar Rules | DSIRE"}], "status": "limited"},
  "Maine": {"landscape": "Maine has a robust community solar ecosystem, but no policies specifically target community-owned solar.", "policies": {"vnm": {"status": "No", "text": "Virtual/remote net metering is not mentioned in state legislation."}, "cs": {"status": "Yes", "text": "Legislation requires investor-owned electric utilities to provide inclusive community solar capacity. Utilities with more than 500,000 customers must provide at least 50 MW by February 1, 2026, and an additional 50 MW by February 1, 2027 (including unclaimed capacity from the previous cycle). Utilities with 500,000 or fewer customers must provide 3.5 MW by February 1, 2026, and an additional 3.5 MW by February 1, 2027.\nSubscribers receive bill credits proportional to their share of the facility’s output **(SB 24-207).**"}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists, but a related program is available.** In April 2024, the U.S. Environmental Protection Agency (EPA) selected Maine for a $62 million grant under the Solar for All (SFA) program. This funding aims to provide financial and technical assistance to enable low-income and disadvantaged households across the state to access solar energy and energy storage solutions. The program also supports workforce development opportunities to ensure quality clean energy jobs for disadvantaged communities. Maine is also a member of the Community Power Coalition, which received $249 million in SFA funding."}}, "details": {"size": "Nameplate capacity of no more than 5 MW **(Net Energy Billing).**", "eligibility": "**Target Audience:** The program is specifically designed to benefit low-income and disadvantaged households in Maine. **Specific Requirements:** As of now, detailed eligibility criteria have not been finalized. The Governor's Energy Office (GEO) plans to solicit public input throughout 2024 to shape the program's design and implementation, including defining specific eligibility requirements. **(Net Billing)**", "benefitDist": "​No specific distribution instructions are described."}, "activeCities": "Communities across the state have installed community solar projects. As of August 2025, Maine had approximately 936 MW of operating community solar, making it the second-largest market in the U.S., following New York. The state also had the second-most solar installed (278 MW) in 2024.", "sources": [{"url": "https://ilsr.org/articles/maines-community-solar-program/", "title": "Maine's Community Solar Program | ILSR"}, {"url": "https://ilsr.org/articles/community-solar-tracker/", "title": "Community Solar Tracker | ILSR"}, {"url": "https://www.poweradvisoryllc.com/reports/maines-community-solar-program-becomes-second-largest-in-the-country-amid-lucrative-rates", "title": "Maine’s Community Solar program becomes second largest in the country amid lucrative rates‍"}, {"url": "https://mainesolarsolutions.com/installation-map/", "title": "Installation Map | Maine Solar Solutions"}, {"url": "https://www.maine.gov/mpuc/regulated-utilities/electricity/neb", "title": "Net Energy Billing"}, {"url": "https://www.mainelegislature.org/legis/bills/bills_129th/billtexts/SP056501.asp", "title": "LD 1711"}, {"url": "https://www.mainelegislature.org/legis/bills/getPDF.asp?paper=SP0815&item=1&snum=131", "title": "LD 1986"}, {"url": "https://legislature.maine.gov/legis/bills/getPDF.asp?paper=HP0692&item=1&snum=130", "title": "LD 936"}, {"url": "https://legislature.maine.gov/legis/bills/getPDF.asp?paper=SP0148&item=1&snum=131", "title": "LD 327"}, {"url": "https://www.mainelegislature.org/legis/bills/bills_129th/billtexts/SP034701.asp", "title": "LD 1127"}], "status": "active"},
  "Maryland": {"landscape": "Maryland allows several different frameworks for community solar projects, including a cooperative-owned structure.", "policies": {"vnm": {"status": "Yes", "text": "Agricultural, nonprofit, and municipal organizations can participate in virtual net metering.**\nSenate Bill 143**, the Net Metering Flexibility Act, was passed in May 2023 and became effective on October 1, 2023. The bill allows customer-generators of community solar to accrue net excess generation for an indefinite period, helping customers maintain their credits over the lifetime of the project and stabilize them during seasonal changes in solar output."}, "cs": {"status": "Yes", "text": "In 2023, HB 908 extended Maryland’s previous seven-year pilot program for community solar, allowing unlimited statewide capacity. **Senate Bill 469**, passed in 2023, established a specialized Task Force to Study Solar Tax Incentives. Its primary goal regarding solar energy was to examine how the state's tax strategies compared with those of other states to promote both rooftop and grid-connected solar installations and expand equitable access to renewable energy for Marylanders."}, "other": {"status": "Yes", "text": "Municipalities, cooperatives, and businesses may own community solar projects, meaning that the state sanctions community-owned solar. In addition, Maryland received $62 million from the federal government under the Solar For All program. The state is also a member of the Community Power Coalition and Clean Energy Fund of Texas, which received $249 million and $156 million in additional SFA funding, respectively. Maryland is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million in SFA funding."}}, "details": {"size": "Community solar projects can be up to 5 MW. Across the state, net metering, including virtual net metering, is capped at 3000 MW total.", "eligibility": "Projects must have at least two subscribers, none of whom occupies more than 60% of the subscription capacity, more than 200% of their baseline annual usage, or more than 200%, or exceeds 200 kW total.", "benefitDist": "Maryland has installed at least 161 MW of community solar as of July 2025. At least 40% of each community solar project must serve low and moderate-income households."}, "activeCities": "Residents of the BGE, Pepco, Potomac Edison, and Delmarva Power utility service areas may access community solar.", "sources": [{"url": "https://ilsr.org/articles/marylands-community-solar-program/", "title": "Maryland’s Community Solar Program - ILSR Energy Democracy Initiative"}, {"url": "https://mdcommunitysolar.org/", "title": "Maryland Community Solar"}, {"url": "https://energy.maryland.gov/Pages/MarylandCommunitySolar.aspx", "title": "Maryland Community Solar (Energy Administration)"}, {"url": "https://solarunitedneighbors.org/resources/net-metering-in-maryland/", "title": "Net metering in Maryland - Solar United Neighbors"}, {"url": "https://programs.dsireusa.org/system/program/detail/363", "title": "Net Metering"}, {"url": "https://seia.org/state-solar-policy/maryland-solar/", "title": "Maryland – SEIA"}, {"url": "https://mgaleg.maryland.gov/2023RS/bills/hb/hb0908E.pdf", "title": "House Bill 908"}, {"url": "https://www.psc.state.md.us/electricity/the-electricity-division/community-net-metering/", "title": "Net Metering - Electricity"}, {"url": "https://solarlandscape.com/news/solar-landscape-energizes-14-new-community-solar-projects-in-maryland/", "title": "Solar Landscape Energizes 14 New Community Solar Projects in Maryland"}], "status": "active"},
  "Massachusetts": {"landscape": "The state has fostered a robust community solar landscape through legislation that encourages small-scale solar, particularly for lower-income residents, and through net metering programs. Community-owned solar is incorporated into these initiatives through the SMART program’s Community Shared Solar incentives.", "policies": {"vnm": {"status": "Yes", "text": "The term “virtual net metering” is not specifically referenced, but the mechanism is codified into law **(Session Law - Acts of 2016 Chapter 75)**. In particular, customers who generate more than they consume are afforded a credit on their electric bill. These credits roll over. If a facility generates more than its subscribers use in total, the utility determines how to allocate credits **(General Law - Part I, Title XXII, Chapter 164)**."}, "cs": {"status": "Yes", "text": "The state requires its largest utility providers to support community solar through virtual net metering and the SMART program. In addition, Massachusetts incentivizes shared solar projects, including access for low-income communities, by reserving 5% of SMART capacity for this purpose."}, "other": {"status": "Yes", "text": "**Green Communities Program:** This program, founded in 2008, provides municipalities with grants for renewable energy projects. **Solar Massachusetts Renewable Target (SMART) Program:** A solar system owner’s utility will pay them proportionally to the energy produced. Both residential and industrial solar systems can qualify. According to an NREL study from June 2024, the SMART program accounts for 59% of Massachusetts’ total community solar development, and the majority of SMART generation is paired with energy storage technology. **Clean Energy Law:** The Clean Energy Law, which passed in November 2024, incentivizes renewable development in general, including solar. In addition, Massachusetts received $156 million from the federal Solar for All (SFA) program and is a member of the multistate Community Power Coalition, which received $249 million from SFA. It is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million of SFA funding."}}, "details": {"size": "Community solar projects are capped at 5 MW, and net metering projects are capped at 2 MW for a private facility or 10 MW for a public one. In addition, both community solar and net metering projects are categorized for different credit rates based on wattage.", "eligibility": "Community solar projects can be operated by residential, industrial, nonprofit, or municipal entities. If a SMART project is also a community solar project, then all participants must use the same utility.", "benefitDist": "The SMART program grants “adders” (additional incentives) to community solar projects, low-income owners, and shared projects that provide at least 50% of electricity benefits to low-income participants."}, "activeCities": "While there are community solar facilities across the state, projects are more concentrated in the southern and eastern regions.", "sources": [{"url": "https://malegislature.gov/Laws/SessionLaws/Acts/2016/Chapter75", "title": "Acts of 2016 Chapter 75 - Session Law"}, {"url": "https://malegislature.gov/Laws/SessionLaws/Acts/2008/Chapter169", "title": "Session Law - Acts of 2008 Chapter 169"}, {"url": "https://www.mass.gov/info-details/solar-massachusetts-renewable-target-smart-program#:~:text=The%20SMART%20Program%20is%20a,incentive%20rates%20between%20each%20block", "title": "Solar Massachusetts Renewable Target"}, {"url": "https://malegislature.gov/Laws/SessionLaws/Acts/2024/Chapter239", "title": "Session Law - Acts of 2024 Chapter 239"}, {"url": "https://malegislature.gov/Laws/GeneralLaws/PartI/TitleXXII/Chapter164/Section140", "title": "General Law - Part I, Title XXII"}, {"url": "https://goclean.masscec.com/clean-energy-solutions/community-solar/", "title": "Community Solar - Clean Energy Lives Here"}, {"url": "https://www.mass.gov/info-details/net-metering-guide", "title": "Net metering guide |"}, {"url": "http://mass.gov", "title": "Mass.gov"}, {"url": "https://www.mass.gov/orgs/green-communities-division", "title": "Green Communities Division |"}, {"url": "https://docs.nrel.gov/docs/fy25osti/91361.pdf", "title": "Sharing the Sun: Community Solar Deployment and Subscriptions"}, {"url": "https://www.mass.gov/news/governor-healey-signs-climate-law-to-advance-clean-energy-transition-create-jobs-and-lower-costs", "title": "Governor Healey Signs Climate Law to Advance Clean Energy Transition, Create Jobs and Lower Costs |"}, {"url": "https://www.solarreviews.com/blog/massachusetts-smart-program-replaces-srecs", "title": "Massachusetts Smart Program Explained"}, {"url": "https://www.nationalgridus.com/solar-hub/Solar-for-Your-Home/CommunitySolar", "title": "Community Solar | National Grid"}, {"url": "https://www.eversource.com/content/residential/save-money-energy/clean-energy-options/solar-energy/community-solar", "title": "Community Solar | Ever"}, {"url": "https://goclean.masscec.com/article/how-to-find-a-community-solar-project-in-massachusetts/", "title": "How To Find a Community Solar Project in Massachusetts"}], "status": "active"},
  "Michigan": {"landscape": "Michigan does not currently have any legislation explicitly enabling community-owned solar.", "policies": {"vnm": {"status": "No", "text": "The state appears to allow net metering but has no policies specifically enabling virtual or remote net metering."}, "cs": {"status": "No", "text": "Michigan does not currently have any legislation explicitly enabling community solar, despite several pushes in the state legislature to do so. All community solar programs are managed by local utilities. The lack of statewide legislation is reflected in the state’s community solar capacity. Per the Solar Energy Industries Association, of the approximately 2,100 MW of solar capacity installed in Michigan, most is utility-owned, with residential installations the second-most prominent."}, "other": {"status": "No", "text": "Michigan does not have any additional support for community-owned solar. However, the state received $156 million in federal Solar For All funding in 2024. This funding will target rooftop solar, not community or community-owned solar. In addition, Michigan is a member of the multistate Industrial Heartland Solar Coalition and the Community Power Coalition, which received $156 million and $249 million in SFA funding, respectively. It is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million from SFA."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Several municipalities across the state have instituted community solar programs, including Ann Arbor, which is also developing a community-owned Sustainable Energy Utility that will incorporate solar power.", "sources": [{"url": "https://www.michigan.gov/egle/about/organization/materials-management/energy/renewable-energy/mi-solar-communities", "title": "MI Solar Communities"}, {"url": "https://micommunitysolar.org/", "title": "MI Community Solar"}, {"url": "https://www.michiganpublic.org/environment-climate-change/2025-01-07/community-solar-gets-bipartisan-bi-peninsular-support-big-utilities-say-its-a-bad-idea", "title": "Community solar gets bipartisan, bi-peninsular support. Big utilities say it’s a bad idea."}, {"url": "https://planetdetroit.org/2024/10/michigan-community-solar-legislation/", "title": "VOICES: For jobs and survival, Michigan needs community solar now"}, {"url": "https://www.michigan.gov/-/media/Project/Websites/mpsc/consumer/info/tips/Net_Metering.pdf?rev=178e8e0e69ab4bc19cc3d359c3b540e1", "title": "Distributed Generation Program & Net Metering"}, {"url": "https://www.solarreviews.com/blog/michigan-net-metering", "title": "Solar Net Metering In Michigan: What Homeowners Need To Know"}, {"url": "https://seia.org/state-solar-policy/michigan-solar/", "title": "Michigan – SEIA"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "Solar for All | US EPA"}, {"url": "https://detroitmi.gov/government/mayors-office/office-sustainability/energy/solar-neighborhoods", "title": "Solar Neighborhoods - City of Detroit"}, {"url": "https://www.a2gov.org/sustainability-innovations-home/sustainability-me/for-families-individuals/solar-in-ann-arbor/", "title": "Solar in Ann Arbor"}, {"url": "https://www.escanaba.org/electric/page/solar-information", "title": "Solar Information | Escanaba"}, {"url": "https://insideclimatenews.org/news/23052024/inside-clean-energy-michigan-upper-peninsula-community-solar/", "title": "Want to See Community Solar Done Right? A Project in Michigan’s Upper Peninsula Can Serve as a Model"}, {"url": "https://planetdetroit.org/2024/06/michigan-community-solar/", "title": "Bipartisan advocates say it’s time for community solar in Michigan"}, {"url": "https://solutions.dteenergy.com/dte/en/Products/MIGreenPower-Community-Impact/p/MIGPSOLAR", "title": "MIGreenPower Community Impact | Products"}, {"url": "https://govmarketnews.com/ann-arbor-establishes-community-owned-sustainable-energy-utility/", "title": "Ann Arbor establishes community-owned sustainable energy utility"}, {"url": "https://theconversation.com/ann-arbors-sustainable-energy-utility-aims-to-build-the-electric-power-grid-of-the-future-alongside-the-old-one-247189", "title": "Ann Arbor’s sustainable energy utility aims to build the electric power grid of the future − alongside the old one"}], "status": "limited"},
  "Minnesota": {"landscape": "Minnesota’s net metering and solar garden programs explicitly allow for cooperative or community-owned structures.", "policies": {"vnm": {"status": "Yes", "text": "The state enables virtual net metering for solar, with compensation rates based on project size, utility costs, and the source’s status as a cooperative, municipal, or public utility. Both net metering and net billing are available for customers of small solar power systems."}, "cs": {"status": "Yes", "text": "Minnesota’s “solar garden” program includes community solar projects, which may be owned by a community or cooperative. In the 2024-25 legislative session, legislators introduced SB 2855, which would have imposed a sunset date for the community solar gardens. This bill did not pass."}, "other": {"status": "Yes", "text": "Minnesota’s policies, as detailed in Minnesota Statutes 2024, Section 216B.1641, allow both communities and municipalities to own solar projects. The state’s Solar on Public Buildings program provides grants to local governments to install solar systems on municipal buildings. In addition, Minnesota has received over $62 million in federal funding under the Solar For All (SFA) program. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "Community solar projects must generate at most 5 MW and have at least 25 subscribers, none of whom owns more than 40% of the project.", "eligibility": "Community solar gardens must have at least 30% of subscribers be LMI, or at least 55% of subscribers be either LMI, public-interest subscribers, or affordable housing providers.", "benefitDist": "The state considers the benefits delivered to “public, nonprofit, cooperative, and Tribal” entities, as well as workforce development opportunities, especially for citizens of color."}, "activeCities": "Communities across the state, including populous municipalities like the Twin Cities, have installed solar gardens. As of August 2025, the state has 931 MW of operating community solar.", "sources": [{"url": "https://mn.gov/puc/consumers/solar-panels-and-net-metering/", "title": "Net Metering & Compensation / Public Utilities Commission"}, {"url": "https://www.revisor.mn.gov/statutes/cite/216B.1641/pdf", "title": "Minnesota Statutes 2024, Section 216B.1641"}, {"url": "https://assets.senate.mn/committees/2025-2026/3122_Committee_on_Energy_Utilities_Environment_and_Climate/Energy-20250326-SenateFile2855-CCSA.pdf", "title": "Minnesota 2024 LMI CSG Study Summary"}, {"url": "https://programs.dsireusa.org/system/program/detail/282", "title": "Net Metering"}, {"url": "https://mn.gov/commerce/energy/consumer/energy-programs/solar-public-buildings.jsp", "title": "Solar on Public Buildings / Minnesota Department of Commerce - Energy"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "Solar for All | US EPA"}, {"url": "https://mn.gov/commerce/energy/consumer/energy-programs/community-solar-gardens.jsp", "title": "Community Solar Gardens -"}, {"url": "http://minnesota.gov", "title": "Minnesota.gov"}, {"url": "https://pv-magazine-usa.com/2025/03/25/minnesota-legislation-aims-to-sunset-community-solar-program/", "title": "Minnesota legislation aims to sunset the community solar program"}, {"url": "https://www.mnseia.org/minnesota-community-solar-gardens", "title": "Minnesota Community Solar Gardens"}, {"url": "https://ilsr.org/articles/minnesotas-community-solar-program/", "title": "Minnesota’s Community Solar Program"}, {"url": "https://ilsr.org/articles/community-solar-tracker/", "title": "Community Solar Tracker - ILSR"}, {"url": "https://www.canarymedia.com/articles/solar/minnesota-save-community-energy-bill", "title": "Minnesota community solar makes it past bipartisan attempt to end program"}, {"url": "https://www.nahro.org/journal_article/saint-paul-housing-authority-saves-with-solar/", "title": "Saint Paul Housing Authority Saves with Solar"}], "status": "active"},
  "Mississippi": {"landscape": "The state has not enabled community-owned solar through any policies.", "policies": {"vnm": {"status": "No", "text": "Mississippi allows net metering, including third-party-owned (TPO) net metering, and participants are paid based on the avoided cost plus a Public Service Commission-approved adder of 2.5 cents/kWh. However, the state does not appear to enable virtual net metering."}, "cs": {"status": "No", "text": "Mississippi has no policies explicitly targeting community solar and was listed as having zero community solar projects as of 2024."}, "other": {"status": "No", "text": "The state has not implemented any programs specifically targeting community-owned solar. However, Mississippi has received federal support for solar projects more generally. In 2024, the Hope Enterprise Corporation was awarded $62 million to implement rooftop solar projects (not community solar) in Mississippi under the federal Solar for All program. In addition, Mississippi is part of the multi-state Community Power Coalition, Clean Energy Fund of Texas, and Southeast Rural Power Coalition, which received $249 million, $156 million, and $156 million, respectively, in additional SFA funding to empower low-income communities, primarily through rooftop solar installations."}}, "details": {"size": "N/A", "eligibility": "The first thousand low-income customers to implement net metering receive an additional 2 cents per kWh on their credits.", "benefitDist": "N/A"}, "activeCities": "As of August 2025, Mississippi has no community solar projects.", "sources": [{"url": "https://www.altuspower.com/post/is-community-solar-available-in-my-state", "title": "Is Community Solar Available in My State?"}, {"url": "https://www.energy.gov/sites/default/files/2024-07/Opportunity%20States_EMP_tech-brief_06.26.2024.pdf", "title": "Community Solar For Opportunity States"}, {"url": "https://www.psc.ms.gov/sites/default/files/Solar%20Consumer%20Guide%20AGO%20October%202021.pdf", "title": "Net Metering and Solar Power in Mississippi"}, {"url": "https://programs.dsireusa.org/system/program/detail/5841", "title": "Net metering programs"}, {"url": "https://www.utilitydive.com/news/mississippi-rooftop-solar-low-income-PSC-net-metering/627245/", "title": "New Mississippi rule requires utilities to pay low-income customers up front for solar installations"}, {"url": "https://www.energy.gov/eere/solar/community-solar-basics", "title": "Community Solar Basics | Department of Energy"}, {"url": "https://www.audubon.org/news/mississippi-tapped-62-million-solar-all-program", "title": "Mississippi Tapped for $62 Million Solar For All Program | Audubon"}], "status": "limited"},
  "Missouri": {"landscape": "Missouri hosts several community solar projects, but the state requires none. There are active legislative efforts to establish mandated community solar programs and provide a statewide framework, which may enable development.", "policies": {"vnm": {"status": "No", "text": "Virtual/remote net metering is not mentioned in state legislation. Traditional net metering is mandated by the Net Metering and Easy Connection Act, which requires all electric utilities to offer net metering to customers with systems of up to 100 kilowatts (kW) in capacity."}, "cs": {"status": "No", "text": "The state does not have any mandated community solar frameworks. **Senate Bill 386** and companion **House Bill 662** are currently pending bills that propose establishing a community solar pilot program. The program would require each retail electric supplier to implement a three-year pilot program spanning 2026 to 2028. Each retail electric supplier must continue running its community solar pilot program until total demand for solar electricity reaches 5% of the supplier’s prior-year electricity sales. These bills are similar to **Senate Bill 1347** and **HB 2574** from the 2024 session, which did not advance out of committee."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Missouri for a $156 million grant under the Solar for All program. The Missouri Environmental Improvement and Energy Resources Authority (EIERA) will provide a combination of forgivable loans to enable solar adoption and support for disadvantaged communities. In addition, Missouri is a member of the Industrial Heartland Solar Coalition, which received $156 million in SFA funding."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "St. Louis and its surrounding areas demonstrate significant activity with multiple community solar centers (Ameren’s Community Solar) and high customer participation.", "sources": [{"url": "https://dnr.mo.gov/print/document-search/pub2238", "title": "https://dnr.mo.gov/print/document-search/pub2238"}, {"url": "https://programs.dsireusa.org/system/program/detail/2621", "title": "https://programs.dsireusa.org/system/program/detail/2621"}, {"url": "https://www.senate.mo.gov/25info/BTS_Web/Bill.aspx?SessionType=R&BillID=167", "title": "https://www.senate.mo.gov/25info/BTS_Web/Bill.aspx?SessionType=R&BillID=167"}, {"url": "https://house.mo.gov/BillContent.aspx?bill=HB662&year=2025&code=R", "title": "https://house.mo.gov/BillContent.aspx?bill=HB662&year=2025&code=R"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://www.ameren.com/missouri/residential/clean-energy-customer-programs/solar/community-solar", "title": "https://www.ameren.com/missouri/residential/clean-energy-customer-programs/solar/community-solar"}], "status": "limited"},
  "Montana": {"landscape": "In the absence of a statewide enabling policy, Montana’s community-owned solar landscape relies primarily on rural electric cooperatives. However, the future of pending legislation may provide further support for community solar development.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote net metering is not contemplated in state legislation. Traditional net metering applies to investor-owned utilities and has a system capacity limit of 50 kW. **(Montana Code § 69-8-601)** According to Montana's Department of Environmental Quality, all electric cooperatives have voluntarily adopted net-metering policies."}, "cs": {"status": "No", "text": "**Senate Bill 188**, known as the Solar Shares Act, was passed by both chambers earlier this year. The Act would have allowed shared solar facilities with a generating capacity of 50 kW to 5 MW and enabled subscriptions for any non-customer generators within the service territory. However, as of July 2025, the bill remains held up by Governor Greg Gianforte’s June 9th veto. Gianforte explains that the “lack of guidance to and guardrails on the PSC” concerns him. The override poll is in progress."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected West Virginia for a $43 million grant under the Solar for All (SFA) program. The Montana SFA Program targets low-income, Tribal, and disadvantaged communities, aiming to increase residential solar access through technical and financial support. Additionally, the Montana **Alternative Energy Revolving Loan Program** (AERLP) offers low-interest loans for renewable projects—including those led by individuals, non-profits, and municipalities—up to 1 MW, which can support the construction of community-owned systems. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Most of Montana’s community solar projects are implemented by rural electric cooperatives. Missoula County, for example, has three operating community solar projects, developed by Missoula Electric Cooperative under their Solarshare program.", "sources": [{"url": "https://archive.legmt.gov/bills/mca/title_0690/chapter_0080/part_0060/sections_index.html", "title": "https://archive.legmt.gov/bills/mca/title_0690/chapter_0080/part_0060/sections_index.html"}, {"url": "https://deq.mt.gov/energy/Programs/renewable", "title": "https://deq.mt.gov/energy/Programs/renewable"}, {"url": "https://bills.legmt.gov/#/laws/bill/2/LC2812", "title": "https://bills.legmt.gov/#/laws/bill/2/LC2812"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://deq.mt.gov/energy/Programs/AERLP", "title": "https://deq.mt.gov/energy/Programs/AERLP"}, {"url": "https://missoulaelectric.com/energy-efficiency/community-solar/", "title": "https://missoulaelectric.com/energy-efficiency/community-solar/"}], "status": "limited"},
  "Nebraska": {"landscape": "Nebraska lacks statewide community solar policies, but utility-led and grant-supported programs provide access to community solar.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote net metering is not mentioned in state legislation. However, Nebraska has established statewide traditional net metering rules for all electric utilities. Under **Legislative Bill 436**, all utilities must provide net metering until the total capacity of all customer-generators reaches 1% of the utility’s average monthly peak demand for the year."}, "cs": {"status": "No", "text": "The state does not have any mandated community solar frameworks. While there is no state community solar law, opportunities to participate in community solar are available. The Nebraska Public Power District offers its **SunWise Community Solar Program** to customers in Ainsworth, Kearney, Norfolk, Ogallala, Scottsbluff, Venango, and York. There have also been past legislative efforts to provide financial support for community solar development. For example, **LB 610** proposed the Community Solar Energy Economic Development Act, which would authorize the Nebraska Environmental Trust Board to consider community solar grants that cover up to 25% of project costs. The bill was postponed indefinitely."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Nebraska for a $62 million grant under the Solar for All program. The program focuses on expanding access to low-income and disadvantaged households. Among other goals, Nebraska SFA provides opportunities for ownership and focuses on residential solar. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding. Additionally, the Department of Water, Energy, and Environment, with a $307 million grant awarded by the EPA, offers the **ONE RED Rural Community Solar Program**, which provides full funding for rural communities to install solar arrays at critical infrastructure sites. The program has $16 million in available funding and plans to support 8 to 20 community projects. This opportunity is only available to low-income or disadvantaged communities."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The Sunwise Community Solar program generates the majority of community solar activity in Nebraska. Active participation is highlighted in Ainsworth, Kearney, Norfolk, Scottsbluff, Ogallala, Venango, and York.", "sources": [{"url": "https://nebraskalegislature.gov/FloorDocs/101/PDF/Final/LB436.pdf", "title": "https://nebraskalegislature.gov/FloorDocs/101/PDF/Final/LB436.pdf"}, {"url": "https://nebraskalegislature.gov/FloorDocs/105/PDF/Intro/LB610.pdf", "title": "https://nebraskalegislature.gov/FloorDocs/105/PDF/Intro/LB610.pdf"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://www.nppd.com/powering-nebraska/solar/community-solar", "title": "https://www.nppd.com/powering-nebraska/solar/community-solar"}, {"url": "https://programs.dsireusa.org/system/program/detail/3386", "title": "https://programs.dsireusa.org/system/program/detail/3386"}, {"url": "https://dee.nebraska.gov/aid/one-red-opportunity-nebraska-reducing-emissions-decarbonization/implementation-grant/one-red-rural-community-solar-program", "title": "https://dee.nebraska.gov/aid/one-red-opportunity-nebraska-reducing-emissions-decarbonization/implementation-grant/one-red-rural-community-solar-program"}], "status": "limited"},
  "Nevada": {"landscape": "Implementation of the state community solar requirement has been slower than expected. As of July 2025, NV Energy has completed three community-based installations mandated by the statewide community solar program.", "policies": {"vnm": {"status": "No", "text": "Virtual or remote net metering is not mentioned in state legislation. Traditional net metering is available for systems up to 1 MW; however, systems exceeding 25 kW may incur costs. As of July 2025, the Public Utilities Commission (PUC) is considering changes proposed by Nevada Power and Sierra Pacific Power in Commission dockets 25-02016 and 25-03006."}, "cs": {"status": "Yes", "text": "**Assembly Bill 465** requires the Public Utilities Commission to establish standards for an expanded solar access program, namely the Community-Based Solar Resource program, which includes advancing community-based solar development as well as a mandate for the electric utility to create at least three (and not more than ten) community-based solar resources within its service territory. **Assembly Bill 458**, enacted in June 2025, expands solar access for renters and low-income families living in multifamily affordable housing, removing red tape so landlords can install rooftop solar and pass the direct cost savings on to tenants. As part of broader community-based solar initiatives, the legislation also raised the maximum nameplate capacity for community-based solar projects from 1 megawatt up to 5 megawatts, allowing larger projects to serve more people."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Nevada for a $156 million grant under the Solar for All program. The program targets low-income and disadvantaged communities by providing financial and technical assistance. Nevada SFA focuses on three major areas, including administering statewide financial support for residential-serving community solar. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "There is a nameplate capacity restriction of 1 MW.", "eligibility": "Eligibility applies regardless of whether customers own, rent, or lease—all customers within NV Energy’s service territory may subscribe.", "benefitDist": "The program capacity is to be divided as follows: 25% must be reserved for low-income customers, another 25% for disadvantaged businesses or nonprofits (i.e., those owned by women, veterans, racial minorities, or members of other underrepresented groups), and 50% for fully residential customers who cannot install on-site solar."}, "activeCities": "As of July 2025, NV Energy offers three sites (one in Reno, two in Las Vegas): City of Reno, with a 409-kilowatt capacity; Freedom Park, with a 480-kilowatt capacity; and Mojave High School, with 773 megawatt-hours per year.", "sources": [{"url": "https://thenevadaindependent.com/article/as-community-solar-spreads-nationwide-nevadas-modified-system-lagging-behind", "title": "As community solar spreads nationwide, Nevada’s ‘modified’ system lagging behind"}, {"url": "https://www.leg.state.nv.us/Session/79th2017/Bills/AB/AB405_EN.pdf", "title": "https://www.leg.state.nv.us/Session/79th2017/Bills/AB/AB405_EN.pdf"}, {"url": "https://www.leg.state.nv.us/App/NELIS/REL/80th2019/Bill/6889/Text", "title": "https://www.leg.state.nv.us/App/NELIS/REL/80th2019/Bill/6889/Text"}, {"url": "https://programs.dsireusa.org/system/program/detail/372", "title": "https://programs.dsireusa.org/system/program/detail/372"}, {"url": "https://www.nvenergy.com/cleanenergy/solar/community-based-solar-resources", "title": "https://www.nvenergy.com/cleanenergy/solar/community-based-solar-resources"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}], "status": "active"},
  "New Hampshire": {"landscape": "New Hampshire is actively expanding its community solar landscape through a state-legislated LMI program and targeted support funded by Solar for All grants.", "policies": {"vnm": {"status": "Yes", "text": "Virtual net metering is enabled through the Group Net Metering law."}, "cs": {"status": "Yes", "text": "New Hampshire’s community solar development is governed under its Group Net Metering law, established by **Senate Bill 98**, which permitted net-metering facilities (hosts) to share the proceeds from surplus generation with other utility account holders (group members). **Senate Bill 165** establishes an LMI community solar program, enabling participation in eligible projects with a 2.5¢-per-kWh credit adder. **Senate Bill 270** establishes an annual cap on LMI projects and, on an opt-out basis, enrolls qualifying customers in projects that will receive the LMI Adder. **Senate Bill 161** amends the definition of \"low-moderate income community solar project\" to allow certain public housing authority projects to qualify as such. This broadens the range of projects that are eligible to receive funding through NH’s Renewable Energy Fund and additional net metering compensation. It has been effective since September 26, 2023."}, "other": {"status": "Yes", "text": "The state community solar program does not restrict who can own community solar projects. Federal support is also available. The U.S. Environmental Protection Agency (EPA) selected New Hampshire for a $43 million grant under the Solar for All program. The NH SFA program offers a comprehensive approach for increasing access to residential-serving community solar. The NH Community Loan Fund targets resident-owned communities, supporting residents' ownership and formation of cooperatives. NH Housing will install community solar serving residential communities on workforce housing projects. The NHDOE will expand its existing community solar program. Additionally, the Municipal Solar Grant Program is a federally funded, competitive grant to fund small solar systems with a total installed capacity under 60 kW DC. All funding ($1.6 million formula grant) has been allocated to 16 municipalities. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "Large customer generators’ capacity is limited to 100 kW to 1 MW, municipal generators are limited to 1 MW to 5 MW, and LMI community solar must not exceed a total nameplate capacity of 6 MW in annual aggregation.", "eligibility": "To qualify for the LMI credit adder, community solar projects must either supply electricity to at least five residential customers, with the majority earning no more than 300% of the federal poverty level, or directly serve a public housing community where most residents have incomes at or below 80% of the area median income.", "benefitDist": "For LMI projects, no more than 15% of the projected load must be dedicated to non-residential customers, and at least 12% of the monthly credit must benefit LMI members."}, "activeCities": "The town of Hanover and the city of Lebanon are among the first to offer Community Choice Aggregation under the Community Power Coalition, and the town of Jeffrey is developing what is expected to become the first Group Net Metering solar project.", "sources": [{"url": "https://gc.nh.gov/legislation/2013/SB0098.pdf", "title": "https://gc.nh.gov/legislation/2013/SB0098.pdf"}, {"url": "https://www.energy.nh.gov/renewable-energy/net-metering-and-group-net-metering/group-net-metering", "title": "https://www.energy.nh.gov/renewable-energy/net-metering-and-group-net-metering/group-net-metering"}, {"url": "https://programs.dsireusa.org/system/program/detail/22460/new-hampshire-community-solar-rules", "title": "https://programs.dsireusa.org/system/program/detail/22460/new-hampshire-community-solar-rules"}, {"url": "https://www.energy.nh.gov/nh-senate-bill-270-implementation", "title": "https://www.energy.nh.gov/nh-senate-bill-270-implementation"}, {"url": "https://www.energy.nh.gov/sites/g/files/ehbemt551/files/inline-documents/sonh/group-net-metering-overview-on-line-bill-crediting-lmi-adder.pdf", "title": "https://www.energy.nh.gov/sites/g/files/ehbemt551/files/inline-documents/sonh/group-net-metering-overview-on-line-bill-crediting-lmi-adder.pdf"}, {"url": "https://www.energy.nh.gov/funding-opportunities/funding-opportunities-cities-towns-counties-and-schools/municipal-solar-grant", "title": "https://www.energy.nh.gov/funding-opportunities/funding-opportunities-cities-towns-counties-and-schools/municipal-solar-grant"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}], "status": "active"},
  "New Jersey": {"landscape": "As of April 2025, New Jersey's Community Solar Energy Program has served more than 28,000 subscribers, who have received over $37 million in bill credits and over $7 million in net savings since the program’s start in 2023.", "policies": {"vnm": {"status": "Yes", "text": "Signed December 2023, **P.L.2023, c.190** requires the board to establish a process for remote net metered solar projects serving public entities as receiving customers."}, "cs": {"status": "Yes", "text": "After the unanimous passing of **Assembly Bill 3723/Senate Bill 2314**, **P.L.2018, c.17,** established the state's first pilot community solar program. Due to its success during runtime, **Assembly Bill 4782/Senate Bill 3123** was signed, formally transitioning the pilot program into a permanent **Community Solar Energy Program.** In April 2025, the NJBPU approved the expansion of an additional 250 MW capacity block. Since the initial capacity allocation in November 2023, over 500 megawatts of community solar projects across New Jersey have enrolled in the CSEP. **Senate Bill 4530** then significantly expanded the state’s Community Solar program by requiring the Board of Public Utilities to open registration for an additional 3000 MW of community solar projects by August 1 2025, and requiring the board to accept and approve registrations until either the end of 2029 or the point at which 3000 MW is reached."}, "other": {"status": "Yes", "text": "**P.L. 2023, c. 190** enables the development of a **small solar facilities incentive program** to award SREC-IIs to owners of community solar facilities, as well as remote and conventionally net-metered solar facilities. The program is implemented through the **Successor Solar Incentive (SuSI)** Program, with a two-part hybrid structure:\n- Administratively Determined Incentive (ADI) Program\n- Competitive Solar Incentive (CSI) Program\nADI provides set incentives for net-metered residential/non-residential projects, remote net metering, and community solar projects.\nCSI covers grid supply and large non-residential net-metered projects. Additionally, federal support is available. The U.S. Environmental Protection Agency (EPA) selected New Jersey for a $156 million grant under the Solar for All program. The NJBPU has designed an SFA program targeting four key areas: residential solar, community solar serving residential areas, multifamily solar, and technical assistance and workforce development. Additionally, NJ SFA plans to provide targeted support to low-income and disadvantaged communities. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "Community solar projects and net-metered systems must have a nameplate capacity of 5 MW or less. The small solar facilities incentive program awards remote net metering systems up to 10 MW and conventional net metered facilities up to 5 MW. The program aims to provide SREC-IIs for at least 300 MW of net-metered solar facilities, 150 MW of community solar facilities, and 75 MW of remote net-metered facilities per year over the five years following program establishment.", "eligibility": "Existing solar projects are not eligible to participate in the CSEP. Only new facilities that have not yet begun commercial operation may apply. All customers within the service territory of a New Jersey Electric Distribution Company are eligible to be a community solar subscriber.", "benefitDist": "CSEP projects must reserve at least 51% of capacity for LMI subscribers. ADI awards $70/SREC-II per MWh for non-LMI community solar and $90/SREC-II per MWh for LMI community solar."}, "activeCities": "New Jersey has widespread community solar development across the state. Some notable cities include Jersey City and Hoboken. A successful project example is the Tri-County Solar farm, serving roughly 800 households across Burlington County, Camden County, and Mercer County.", "sources": [{"url": "https://pub.njleg.gov/bills/2018/PL18/17_.PDF", "title": "https://pub.njleg.gov/bills/2018/PL18/17_.PDF"}, {"url": "https://pub.njleg.state.nj.us/Bills/2022/PL23/190_.PDF", "title": "https://pub.njleg.state.nj.us/Bills/2022/PL23/190_.PDF"}, {"url": "https://www.nj.gov/governor/news/news/562024/approved/20240104c.shtml", "title": "https://www.nj.gov/governor/news/news/562024/approved/20240104c.shtml"}, {"url": "https://www.njcleanenergy.com/renewable-energy/programs/susi-program/csep", "title": "https://www.njcleanenergy.com/renewable-energy/programs/susi-program/csep"}, {"url": "https://www.nj.gov/bpu/newsroom/2025/approved/20250423csep.html", "title": "https://www.nj.gov/bpu/newsroom/2025/approved/20250423csep.html"}, {"url": "https://www.njcleanenergy.com/renewable-energy/programs/susi-program", "title": "https://www.njcleanenergy.com/renewable-energy/programs/susi-program"}], "status": "active"},
  "New Mexico": {"landscape": "Although the state’s community solar programs are still under development, New Mexico’s Community Solar Act legitimizes community solar for all residents and preserves existing tribal projects.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote net metering was previously contemplated in the Low-Income Solar Act, as expressed in the following passage:\n“A utility shall provide virtual net metering bill credits equal to the full retail value of the kilowatt-hour to users of low-income housing shared distributed generation systems[...]” (**SB 432)**\nHowever, after reaching the House Taxation & Revenue Committee, progress was postponed indefinitely, killing the bill in that chamber. Traditional net metering in New Mexico is available to all “qualifying facilities” (QFs) as defined under the federal PURPA law, and all utilities regulated by the Public Regulation Commission (PRC) are required to provide net metering."}, "cs": {"status": "Yes", "text": "The **Community Solar Act (Senate Bill 84**) authorized community solar projects in New Mexico. With tribal lands covering 10% of New Mexico, multiple small-scale tribal-owned solar facilities already exist. The Act notes that “nothing in the Community Solar Act shall preclude an Indian nation, tribe, or pueblo from using financial mechanisms other than subscription models, including virtual and aggregate net-metering, for native community solar projects.\""}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected New Mexico for a $156 million grant under the Solar for All program. The program focuses on isolated and disadvantaged communities, expanding access to shared solar beyond the currently defined community solar program. The state is also a member of the Community Power Coalition and Clean Energy Fund of Texas, which received $249 million and $156 million in additional SFA funding, respectively. New Mexico is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million in SFA funding."}}, "details": {"size": "The initial statewide annual capacity was 100 MW, which was proportionally divided among investor-owned utilities. Native community solar projects and rural electric cooperatives are excluded from this calculation. As of November 1, 2024, the new statewide annual capacity is 300 MW. A facility has a nameplate capacity limit of 5 MW.", "eligibility": "Any customer of a qualifying utility may subscribe. There must be at least 10 subscribers, and no single subscriber can exceed 40% of the facility's capacity.", "benefitDist": "The Act requires that 30 percent of each community solar facility be dedicated to low-income households, and at least 40 % of the total capacity must be offered in blocks of 25 kW or less."}, "activeCities": "Valencia County hosts the state’s first community solar project, and many counties, including Doña Ana, Grant, Hidalgo, and Roosevelt, are closely following with newly approved or proposed projects.", "sources": [{"url": "https://www.nmstatelands.org/2025/02/27/commissioner-garcia-richard-approves-six-new-community-solar-projects/?utm_source=chatgpt.com", "title": "https://www.nmstatelands.org/2025/02/27/commissioner-garcia-richard-approves-six-new-community-solar-projects/"}, {"url": "https://programs.dsireusa.org/system/program/detail/284", "title": "https://programs.dsireusa.org/system/program/detail/284"}, {"url": "https://www.srca.nm.gov/parts/title17/17.009.0570.html", "title": "https://www.srca.nm.gov/parts/title17/17.009.0570.html"}, {"url": "https://www.nmlegis.gov/Sessions/23%20Regular/bills/senate/SB0432.pdf", "title": "https://www.nmlegis.gov/Sessions/23%20Regular/bills/senate/SB0432.pdf"}, {"url": "https://www.nmlegis.gov/Sessions/21%20Regular/final/SB0084.pdf", "title": "https://www.nmlegis.gov/Sessions/21%20Regular/final/SB0084.pdf"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://www.prc.nm.gov/utilities/community-solar/", "title": "https://www.prc.nm.gov/utilities/community-solar/"}, {"url": "https://www.prc.nm.gov/wp-content/uploads/2024/10/Press-Release_NMPRC-raises-community-solar-programs-statewide-capacity-cap_CORRECTED-VERSION.pdf", "title": "Press release on cap increase"}], "status": "active"},
  "New York": {"landscape": "Community-owned solar initiatives in New York State are not explicitly defined or mandated by specific legislation.", "policies": {"vnm": {"status": "Yes", "text": "New York enables virtual net metering through its Community Distributed Generation (CDG) program **(NY PSC Case 15-E-0082, 2015).**"}, "cs": {"status": "Yes", "text": "New York has defined community solar as any off-site project that feeds into a local power grid and generates energy for more than 10 subscribers, who can be homes, apartment buildings, small businesses, or local governments. Most projects in the state use a model in which subscribers receive credits on their electric bills for their portion of the energy generated. Private solar developers operate the projects."}, "other": {"status": "No", "text": "The state does not have any other programs explicitly enabling community-owned solar. New York’s Solar for All program allows lower-income citizens (those with less than 60% of the state median income who are not already participating in a solar project) to access community solar at no cost. This program received $250 million from the federal government. The state's Community Distributed Generation (CDG) program, established by the New York Public Service Commission (PSC) in 2015, allows multiple customers to participate in shared renewable energy projects and receive credits on their electricity bills proportional to their share of the project's output. However, this program does not specifically address or require community ownership structures for these projects **(PSC Case 15-E-0082)**. In addition, New York is a member of the Community Power Coalition and Industrial Heartland Solar Coalition, which received $249 million and $156 million of SFA grants, respectively. It is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million in funding."}}, "details": {"size": "A 2018 NRDC announcement states that community solar projects are capped at 5 MW (about 30 acres).", "eligibility": "Projects must include at least 10 subscribers, each of whom can access at least 1,000 kWh per year. Up to 40% of the generated power can be allocated to subscribers with a demand of 25 kW or more.", "benefitDist": "The exact distribution of benefits is unclear. However, the state’s Solar for All program has been a significant contributor to the 6 GW of solar energy installed statewide."}, "activeCities": "Cities across the state have installed community solar projects, including the 1.2 MW Community Power project in Brooklyn, which won a 2023 Sunny Award for Equitable Community Solar.", "sources": [{"url": "https://www.nyseg.com/documents/40132/5899056/NYSEG_CDG_Procedural_Requirements.pdf/a66653eb-05cd-b432-3594-6a4b377265ac?t=1645136496317", "title": "NEW YORK STATE ELECTRIC & GAS CORPORATION 18 LINK DRIVE P.O. BOX 5224 BINGHAMTON, NY 13904 Community Distributed Generation"}, {"url": "https://www.nyserda.ny.gov/All-Programs/NY-Sun/Community-Solar", "title": "Community Solar - NYSERDA"}, {"url": "https://www.nyserda.ny.gov/All-Programs/NY-Sun/Contractors/Resources-for-Contractors/Community-Solar", "title": "Community Solar for Contractors - NYSERDA"}, {"url": "https://www.nyserda.ny.gov/About/Newsroom/2024-Announcements/2024-10-17-Governor-Hochul-Announces-New-York-State-Has-Achieved-Major-Solar-Milestone", "title": "New York State Has Achieved Major Solar Milestone A Year Early - NYSERDA"}, {"url": "https://www.solarlandlease.com/community-solar-farms-in-new-york-state-what-solar-developers-look-for", "title": "Community Solar Farms in New York State: What Solar Developers Look For - SolarLandLease"}, {"url": "https://www.nyserda.ny.gov/All-Programs/Clean-Energy-Siting-Resources/Solar-Guidebook", "title": "New York State Solar Guidebook - NYSERDA"}, {"url": "https://www.nrdc.org/bio/sneha-ayyagari/ny-spurs-community-solar-upping-project-size-threshold", "title": "NY Spurs Community Solar by Upping Project Size Threshold"}, {"url": "https://www.nyserda.ny.gov/All-Programs/NY-Sun/Community-Solar/How-It-Works", "title": "How Community Solar Works"}, {"url": "https://www.nyserda.ny.gov/-/media/Project/Nyserda/Files/Programs/NY-Sun/Solar-for-All/Solar-for-All-FAQs.pdf", "title": "Frequently Asked Questions: Solar for All"}, {"url": "https://pv-magazine-usa.com/2023/07/07/five-organizations-turning-community-solar-into-savings-for-low-income-americans/", "title": "Five organizations turning community solar into savings for low-income Americans"}, {"url": "https://www.c40.org/case-studies/nyc-sunset-park-solar/", "title": "Sunset Park: Community Solar Energy in NYC"}, {"url": "https://web.archive.org/web/20250122095538/https://www.energy.gov/communitysolar/community-power-project-sunny-awards-winner", "title": "Community Power Project: Sunny Awards Winner"}], "status": "active"},
  "North Carolina": {"landscape": "Although North Carolina's community solar development benefits from its state-legislated framework, a state-mandated community solar program under Duke Energy has yet to launch due to financial and design challenges.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote net metering is not mentioned in any state legislation. Traditional net metering follows the North Carolina Utilities Commission's approved revised tariffs under Rider RS (Residential Solar Choice) and Rider NMB (Net Metering Bridge). Residential customers with existing net-metered systems installed before the revision may continue their service until December 31, 2026. Afterward, they will be automatically transitioned to Rider NMB."}, "cs": {"status": "Yes", "text": "Legislation enables community solar by requiring each investor-owned utility to organize a community solar program for Commission approval. **(§ 62‑126.8.)**"}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected North Carolina for a $156 million grant under the Solar for All program. EnergizeNC, the North Carolina SFA program, will focus development in three priority areas: rooftop solar for single-family homes, behind-the-meter solar for multifamily housing, and community solar pilot programs. North Carolina is also a member of the multistate Southeast Rural Power Coalition and Clean Energy Fund of Texas, each of which received $156 million in additional SFA funding, and the Community Power Coalition, which received $249 million in SFA funding. It is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million in SFA funding."}}, "details": {"size": "Each facility is limited to a nameplate capacity of 5 MW, and each utility is capped at 20 MW, for a total of 40 MW between Duke Energy Carolinas and Duke Energy Progress.", "eligibility": "A community solar facility must be within the service territory of the offering utility, and subscribers must be located in the same county as the facility or in an adjacent county.", "benefitDist": "Community solar projects must have at least five subscribers, and no single subscriber can have more than a forty percent (40%) interest."}, "activeCities": "Current operational community solar projects are mostly cooperative-run. Active subscription-based projects are sited in Fayetteville City (PWC Community Solar by the municipal utility PWC) and various counties served by co-op projects, such as Pee Dee Electric Cooperative's Community Solar.", "sources": [{"url": "https://publicstaff.nc.gov/electric/net-metering#Howdoesnetmeteringwork-219", "title": "https://publicstaff.nc.gov/electric/net-metering#Howdoesnetmeteringwork-219"}, {"url": "https://www.ncleg.gov/EnactedLegislation/Statutes/PDF/BySection/Chapter_62/GS_62-126.8.pdf", "title": "https://www.ncleg.gov/EnactedLegislation/Statutes/PDF/BySection/Chapter_62/GS_62-126.8.pdf"}, {"url": "https://www.ncleg.gov/Sessions/2017/Bills/House/PDF/H589v5.pdf", "title": "https://www.ncleg.gov/Sessions/2017/Bills/House/PDF/H589v5.pdf"}, {"url": "https://www.duke-energy.com/home/products/renewable-energy/nc-shared-solar", "title": "https://www.duke-energy.com/home/products/renewable-energy/nc-shared-solar"}, {"url": "https://www.pdemc.com/energy-efficiency/solar/", "title": "https://www.pdemc.com/energy-efficiency/solar/"}, {"url": "https://www.faypwc.com/community-solar/", "title": "https://www.faypwc.com/community-solar/"}], "status": "active"},
  "North Dakota": {"landscape": "In Quarter 1 of 2025, North Dakota ranked last in national solar capacity, according to the Solar Energy Industries Association (SEIA). There is little community solar development in North Dakota due to the lack of enabling policies and a statewide framework.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote Net Metering is not mentioned in any state legislation. However, **North Dakota Administrative Code 69-09-07-09** enables traditional net metering. The policy, adopted in 1991 by the Public Service Commission, applies to systems with capacities up to 100 kilowatts. All investor-owned electric utilities must make net metering available to their customers; net metering is not available to customers of municipal utilities or electric cooperatives."}, "cs": {"status": "No", "text": "North Dakota has no policies enabling community solar. Opportunities to participate in community solar are scarce and remain dependent on independent companies and organizations. In partnership with Empower by Light, GivePower led the effort to build the 300 kW **CannonBall Community Solar Farm**. GivePower and Empower by Light are both non-profit organizations, and their project, representing 50% of North Dakota's Solar Power at the time, demonstrated tribal advocacy for land sovereignty. Cass County Electric Cooperative (CCEC) also offers the **Prairie Sun Community Solar** project, a 102-kW solar array available for lease to CCEC members."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists**. The U.S. Environmental Protection Agency (EPA) selected North Dakota for a $62 million grant under the Solar for All (SFA) program. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million. These programs, however, do not focus on community solar development."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The CannonBall Community Solar Farm serves the Standing Rock Sioux Tribe community, and Prairie Sun is available to all CCEC customers—a portion of southeast North Dakota stretching from Fargo to Ekenston.", "sources": [{"url": "https://seia.org/state-solar-policy/north-dakota-solar/", "title": "https://seia.org/state-solar-policy/north-dakota-solar/"}, {"url": "https://ndlegis.gov/information/acdata/pdf/69-09-07.pdf", "title": "https://ndlegis.gov/information/acdata/pdf/69-09-07.pdf"}, {"url": "https://programs.dsireusa.org/system/program/detail/285", "title": "https://programs.dsireusa.org/system/program/detail/285"}, {"url": "https://givepower.org/2019/07/18/solar-energy-farm-standing-rock-reservation/", "title": "https://givepower.org/2019/07/18/solar-energy-farm-standing-rock-reservation/"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://casscountyelectric.com/renewable-energy", "title": "https://casscountyelectric.com/renewable-energy"}], "status": "limited"},
  "Ohio": {"landscape": "Ohio lacks state policies and incentives for community solar development, though there are active efforts to establish supportive programs that may enable community solar in the future.", "policies": {"vnm": {"status": "No", "text": "Virtual/remote net metering is not enabled by state legislation. However, regulated electric utilities are required to offer traditional net metering to their customers **(Ohio Revised Code § 4928.67)**. There has also been a past effort to enforce virtual net metering: **House Bill 450 (2021)** proposed virtual net metering laws for community solar, but was never passed."}, "cs": {"status": "No", "text": "Ohio has no policies enabling community solar. Introduced in May 2025 and currently pending, **House Bill 303** would establish a community energy program and pilot program with the facility nameplate capacity limited to 10 megawatts or less."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Ohio for a $156 million grant under the Solar for All program. The program targets LMI households and seeks to expand access to solar energy. In addition, Ohio is a member of the Industrial Heartland Solar Coalition and Community Power Coalition, which received $156 million and $249 million, respectively, in supplementary SFA funding."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "There are currently no active community solar programs under the state’s policy.", "sources": [{"url": "https://codes.ohio.gov/ohio-revised-code/section-4928.67", "title": "https://codes.ohio.gov/ohio-revised-code/section-4928.67"}, {"url": "https://ohiohouse.gov/legislation/134/hb450", "title": "https://ohiohouse.gov/legislation/134/hb450"}, {"url": "https://ohiohouse.gov/legislation/136/hb303", "title": "https://ohiohouse.gov/legislation/136/hb303"}], "status": "limited"},
  "Oklahoma": {"landscape": "Due to the lack of enabling policies and a statewide framework for community solar development, Oklahoma's community solar landscape relied primarily on electric cooperatives, which offer community-shared programs and limited community ownership.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote Net Metering is not enabled. However, Oklahoma offers traditional net metering under **17 O.S. § 156** and **OAC 165:40:9.** The maximum customer participation is 300 kW."}, "cs": {"status": "No", "text": "Oklahoma has no policies enabling community solar. Some electric cooperatives have developed community-shared solar programs, such as Northwestern Electric Cooperative's (NWEC) Community Solar Program, with availability limited to 375 shares."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists.** A few electric cooperatives are planning to develop community-owned projects, but there is a lack of state support and dedicated federal funding. Oklahoma did not receive a state-based award in the Solar for All program. However, the state is a member of the Community Power Coalition and Clean Energy Fund of Texas, which received $249 million and $156 million in SFA funds, respectively."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Participation follows the co-op programs’ service territory. NWEC serves 7 counties, including Woodward, Woods, Major, Beaver, and Dewey. East Central Oklahoma Electric Cooperative also offers a community-shared program that serves 9 counties, including portions of Creek, McIntosh, Muskogee, Okfuskee, Okmulgee, Tulsa, and Wagoner counties.", "sources": [{"url": "https://oklahoma.gov/occ/divisions/public-utility/energy/electric-utility/netmetering.html", "title": "https://oklahoma.gov/occ/divisions/public-utility/energy/electric-utility/netmetering.html"}, {"url": "https://www.nwecok.coop/community-solar-program", "title": "https://www.nwecok.coop/community-solar-program"}, {"url": "https://www.ecoec.com/renewable-power", "title": "https://www.ecoec.com/renewable-power"}], "status": "limited"},
  "Oregon": {"landscape": "Oregon’s community solar projects are growing quickly, supported by an established statewide community solar program, federal funding, and state grants.", "policies": {"vnm": {"status": "No", "text": "**Traditional net metering is enabled statewide.** The Public Utilities Commission requires all utilities, including investor-owned, public utility districts, municipalities, and cooperatives, to allow net metering for customers. Residential renewable installations may not exceed 25 kW."}, "cs": {"status": "Yes", "text": "**Senate Bill 1547** first enabled community solar by requiring the Public Utility Commission to “establish by rule a program for the procurement of electricity from community solar projects.” **Senate Bill 688** updates rates and creates an incentive/penalty framework to promote emissions reductions, expand distributed energy, assist low-income payments, and lower ratepayer costs. The **Oregon Community Solar Program** offers both subscription and ownership options. Participant’s ownership or subscription interest is limited to 40 percent of the project, or the retail electricity customer’s average annual consumption of electricity. The three qualifying utilities are Portland General Electric, Pacific Power, and Idaho Power. Additionally, **House Bill 2021** established the **Community Renewable Energy Grant Program**, a competitive grant program to support the planning and development of community renewable energy projects and to expand access, especially for underserved communities. As of June 2025, $24.5 million remains of the total $64.7 million funding. **House Bill 2065** and **House Bill 2066** establish regulatory frameworks for microgrids, allowing third-party consultants to evaluate requests and utilities to reject unsafe connections, setting integration standards for community microgrids, and encouraging localities to designate microgrid zones."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Oregon for an $86 million grant under the Solar for All program. This program targets low-income households, providing financial and technical support for multiple projects, including community solar development. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "Community solar projects must have a minimum of 5 subscribers and a nameplate capacity of 3 MW or less.", "eligibility": "Customers of Pacific Power, Portland General Electric, and Idaho Power can participate in the Community Solar Program. Customers receiving a volumetric incentive rate from an installed renewable energy system are ineligible.", "benefitDist": "Costs vary by project and subscription model. The program offers variable subscription plans (\"pay-as-you-go\") and fixed subscription plans (fixed monthly amount). Low-income households receive a reduced subscription fee of at least 20%, no up-front costs, and no termination fees. Additionally, at least 10 percent of the program’s total capacity must be reserved for low-income residential customers."}, "activeCities": "Portland is actively developing community solar, including a low-income-targeted project in the Cully neighborhood. Clackamas County also hosts multiple community solar projects. Virtual net metering is allowed in the city of Ashland. For Ashland citizens, the policy expands opportunities for off-site solar participation and co-development of larger community systems.", "sources": [{"url": "https://olis.oregonlegislature.gov/liz/2016R1/Downloads/MeasureDocument/SB1547/Enrolled", "title": "https://olis.oregonlegislature.gov/liz/2016R1/Downloads/MeasureDocument/SB1547"}, {"url": "https://olis.oregonlegislature.gov/liz/2025R1/Downloads/MeasureDocument/HB2066/Enrolled", "title": "https://olis.oregonlegislature.gov/liz/2025R1/Downloads/MeasureDocument/HB2066"}, {"url": "https://olis.oregonlegislature.gov/liz/2025R1/Downloads/MeasureDocument/HB2065/Enrolled", "title": "https://olis.oregonlegislature.gov/liz/2025R1/Downloads/MeasureDocument/HB2065"}, {"url": "https://programs.dsireusa.org/system/program/detail/22463/oregon-community-solar-program", "title": "https://programs.dsireusa.org/system/program/detail/22463"}, {"url": "https://www.oregon.gov/puc/utilities/Pages/Renewable-Resources.aspx", "title": "https://www.oregon.gov/puc/utilities/Pages/Renewable-Resources.aspx"}, {"url": "https://olis.oregonlegislature.gov/liz/2025R1/Measures/Overview/SB688", "title": "https://olis.oregonlegislature.gov/liz/2025R1/Measures/Overview/SB688"}, {"url": "https://climate.oregon.gov/climate-conversation-blog/2018/7/11/solar-energy-and-virtual-net-metering-in-ashland", "title": "https://climate.oregon.gov/climate-conversation-blog/2018/7/11/solar-energy-and-virtual-net-metering-in-ashland"}, {"url": "https://olis.oregonlegislature.gov/liz/2021R1/Downloads/MeasureDocument/HB2021", "title": "https://olis.oregonlegislature.gov/liz/2021R1/Downloads/MeasureDocument/HB2021"}, {"url": "https://www.oregon.gov/energy/Incentives/Pages/CREP.aspx", "title": "https://www.oregon.gov/energy/Incentives/Pages/CREP.aspx"}, {"url": "https://www.oregoncsp.org/", "title": "https://www.oregoncsp.org/"}, {"url": "https://www.oregon.gov/energy/Incentives/Pages/Solar-for-All.aspx", "title": "https://www.oregon.gov/energy/Incentives/Pages/Solar-for-All.aspx"}, {"url": "https://www.oregoncsp.org/projectfinder/", "title": "https://www.oregoncsp.org/projectfinder/"}, {"url": "https://apps.puc.state.or.us/orders/2017ords/17-232.pdf", "title": "https://apps.puc.state.or.us/orders/2017ords/17-232.pdf"}], "status": "active"},
  "Pennsylvania": {"landscape": "Pennsylvania currently lacks state frameworks for community solar, but pending legislation may help enable programs in the future; however, community-owned solar requires more specific support.", "policies": {"vnm": {"status": "Yes", "text": "Virtual meter aggregation is enabled for customer-generators on properties they own or lease and operate, provided the meters are located within two miles of the customer’s property and the same electric distribution company’s service territory. **(52 Pa. Code § 75.14.)**"}, "cs": {"status": "No", "text": "Pennsylvania has no policies enabling community solar. However, there are active efforts in pending state legislation to authorize community solar.\n- **House Bill 1842 (2023)** targets community solar, declaring that such programs provide customers with access unconstrained by the physical characteristics of their homes. It also encourages community solar programs to target LMI households and aims to maximize the use of federal funds for community solar.\n- ****House Bill 504 (2025)** is similar but broader, referring to community energy programs instead.**"}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists**, but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Pennsylvania for a $156 million grant under the Solar for All program. Although the Pennsylvania SFA program does not specifically target community solar, it aims to increase the availability and accessibility of solar energy for low-income homeowners and disadvantaged communities. In addition, Pennsylvania is a member of the Industrial Heartland Solar Coalition, the Clean Energy Fund of Texas, and the Community Power Coalition. The first two received $156 million each, and the third received $249 million under the SFA. It is also one of the states prioritized under the Solar Access for Nationwide Affordable Housing Program, which received $250 million in SFA funding."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "There are currently no active community solar programs, but supportive legislation is under review.", "sources": [{"url": "https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/052/chapter75/s75.14.html&d=", "title": "https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/052/chapter75/s75.14.html&d="}, {"url": "https://www.palegis.us/legislation/bills/text/PDF/2025/0/HB0504/PN1628", "title": "https://www.palegis.us/legislation/bills/text/PDF/2025/0/HB0504/PN1628"}, {"url": "https://www.palegis.us/legislation/bills/text/PDF/2023/0/HB1842/PN2789", "title": "https://www.palegis.us/legislation/bills/text/PDF/2023/0/HB1842/PN2789"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}], "status": "limited"},
  "Puerto Rico": {"landscape": "Among a general push for renewable energy, Puerto Rico has seen a proliferation of grassroots community-owned solar and microgrid projects.", "policies": {"vnm": {"status": "Yes", "text": "Puerto Rico established normal net metering in Act 114 of 2007, and Act 133 of 2016 extended this definition to remote net metering. Act 10 of 2024 extended net metering at least through 2030. In 2023, Luma Energy, the island’s electric utility, launched a yearlong pilot for virtual power plants that drew power for the entire grid from individual residences’ rooftop solar/battery systems. As of January 2024, the benefit rates for this program were three times those for net metering, and as of July 2025, the pilot has become a full-fledged program."}, "cs": {"status": "Yes", "text": "Puerto Rico set community solar development as a public policy goal in Act 17 of 2019, and included community solar in its list of distributed renewable energy forms in Act 82 of 2010."}, "other": {"status": "No", "text": "Puerto Rico has not established specific policies supporting community-owned solar rather than community solar more broadly. The territory has received almost $2 billion in federal support for solar systems, including a $1 billion commitment by the U.S. government for the Puerto Rico Energy Resilience Fund."}}, "details": {"size": "Net metered systems are limited to 25 kW for residential, 1 MW for non-residential, and 5 MW for non-residential connected to transmission or subtransmission.", "eligibility": "There are no formal eligibility requirements.", "benefitDist": "There are no benefit distribution instructions set."}, "activeCities": "Puerto Rican communities have embraced community-owned solar, often paired with battery storage, including Casa Pueblo. This community-governed organization has established net-metered solar systems in several neighborhoods on the island.", "sources": [{"url": "http://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/PDF/2-ingles/114-2007.pdf", "title": "Puerto Rico Net Metering Program Act"}, {"url": "https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/PDF/2-ingles/82-2010.pdf", "title": "Public Policy on Energy Diversification by Means of Sustainable and Alternative Renewable Energy in Puerto Rico Act"}, {"url": "https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/PDF/2-ingles/57-2014.pdf", "title": "Puerto Rico Energy Transformation and RELIEF Act"}, {"url": "https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/PDF/2-ingles/0133-2016.pdf", "title": "An Act"}, {"url": "https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/PDF/2-ingles/17-2019.pdf", "title": "Puerto Rico Energy Public Policy Act"}, {"url": "https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/PDF/2-ingles/0010-2024.pdf", "title": "Amendment to Electric Power Authority Net Metering Program"}, {"url": "https://www.honnoldfoundation.org/adjuntas-a-solar-community#adjuntas", "title": "Adjuntas: A Solar Community"}, {"url": "https://casapueblo.org/", "title": "Casa Pueblo"}, {"url": "https://www.letssharethesun.org/casa-pueblo", "title": "Casa Pueblo - Let's Share the Sun"}, {"url": "https://programs.dsireusa.org/system/program/detail/2846/puerto-rico-net-metering", "title": "Puerto Rico - Net Metering (DSIRE)"}, {"url": "https://jpia.princeton.edu/news/renewing-growth-puerto-rico-evaluating-island%E2%80%99s-transition-distributed-solar-energy", "title": "Renewing Growth in Puerto Rico: Evaluating the Island’s Transition to Distributed Solar Energy"}, {"url": "https://justsolutionscollective.org/puerto-rico-and-the-fight-for-energy-democracy/", "title": "Puerto Rico and the fight for Energy Democracy"}, {"url": "https://www.energy.gov/sites/default/files/2023-02/Puerto%20Rico%20Energy%20Resilience%20Fund%20Fact%20Sheet%20%28February%202023%29.pdf", "title": "Puerto Rico Energy Resilience Fund Fact Sheet"}, {"url": "https://time.com/6264631/puerto-rico-adjuntas-solar-microgrid/", "title": "In Puerto Rico, a Small Town Takes Climate Action Into Its Own Hands"}, {"url": "https://www.canarymedia.com/articles/solar/why-puerto-rican-communities-are-all-in-on-solar-microgrids", "title": "Why Puerto Rican communities are all-in on solar microgrids"}, {"url": "https://nextcity.org/features/grassroots-movement-puerto-ricos-first-community-owned-solar-microgrid", "title": "The Grassroots Movement That Built Puerto Rico’s First Community-Owned Microgrid"}, {"url": "https://www.latitudemedia.com/news/puerto-rico-is-using-residents-home-batteries-to-back-up-its-grid/", "title": "Puerto Rico is using residents’ home batteries to back up its grid"}, {"url": "https://pv-magazine-usa.com/2024/04/16/puerto-ricos-solar-net-metering-law-at-risk-from-federal-oversight-board/", "title": "Puerto Rico’s solar net metering law at risk from federal oversight board"}, {"url": "https://ieefa.org/sites/default/files/2024-06/Solar%20at%20a%20Crossroads%20in%20Puerto%20Rico_June%202024_0.pdf", "title": "Solar at a Crossroads in Puerto Rico"}, {"url": "https://www.energy.gov/gdo/articles/us-department-energy-announces-325-million-solar-and-battery-storage-community", "title": "U.S. Department of Energy Announces $325 Million for Solar and Battery Storage for Community Healthcare Facilities and Multi-Family Housing in Puerto Rico"}, {"url": "https://www.canarymedia.com/articles/solar/puerto-rico-rooftop-solar-net-metering-lawsuit-fomb", "title": "Puerto Rico extended a key rooftop solar policy. Then came the lawsuit."}, {"url": "https://pv-magazine-usa.com/2024/11/01/coalition-of-28-organizations-files-brief-in-support-of-continued-net-metering-in-puerto-rico/", "title": "Coalition of 28 organizations files brief in support of continued net metering in Puerto Rico"}, {"url": "https://newsismybusiness.com/puerto-rico-on-its-way-to-growing-1st-virtual-power-plant-in-the-caribbean/", "title": "Puerto Rico on its way to growing ‘1st virtual power plant in the Caribbean’"}, {"url": "https://www.pv-tech.org/us-doe-loans-us1-2-billion-for-puerto-rico-pv-bess/", "title": "US DOE loans US$1.2 billion for Puerto Rico PV/BESS as Biden administration ends"}, {"url": "https://www.utilitydive.com/news/puerto-rico-rooftop-solar-fomb-net-meter-lawsuit-sesa/746182/", "title": "Puerto Rico’s rooftop solar boom is strengthening grid resilience — why is a federal board trying to stop it?"}, {"url": "https://www.utilitydive.com/news/solar-storage-vpp-puerto-ricos-grid-luma-sunrun/753722/", "title": "Booming solar and storage are propping up Puerto Rico’s grid this summer"}, {"url": "https://techxplore.com/news/2025-07-puerto-rico-community-solar-power.html", "title": "Puerto Rico's community-owned solar power: Alternative to frequent blackouts"}, {"url": "https://usasolarcell.com/news/2025/07/25/community-solar-power-in-puerto-rico-fights-blackouts-boldly/", "title": "Community solar power in Puerto Rico fights blackouts boldly"}], "status": "active"},
  "Rhode Island": {"landscape": "With state support, community solar is developing quickly, with eight projects completed, nine projects in development, and more than 6,000 customers signed up to various virtual net metering (VNM) and Community Remote Distributed Generation (CRDG) projects.", "policies": {"vnm": {"status": "Yes", "text": "Rhode Island’s virtual net metering and Community Remote Net Metering (CRNM) programs are enabled and governed by the Rhode Island General Laws, Title 39, Chapter 39‑26.4."}, "cs": {"status": "Yes", "text": "**House Bill 8354** created a CRNM pilot program with a total cap of 30 MW. The program enabled shared solar systems and expanded the maximum eligible system size (for virtual net metering as well) from 5 MW to 10 MW. Community net metered systems could also be owned by a participating customer or financed by a third party. Under **House Bill 5853** and **Senate Bill 684**, the Office of Energy Resources was required to redesign the CRNM program. Additionally, administered by Rhode Island Commerce, the **Rhode Island Renewable Energy Fund (REF)** provides grants that can cover up to 30% of installation costs for projects, including but not limited to community solar. **House Bill 5580**, enacted in June 2025, prohibits utility companies from limiting a net-metering site's eligibility based on prior consumption and requires that excess energy not consumed under the net-metering system be credited to the consumer. It also amends the definition of excess renewable net-metering credit. **Senate Bill 843,** enacted in June 2025, redesigns the state’s community remote net metering program to make shared solar energy more equitable by requiring community solar projects to reserve half their capacity for commercial or industrial anchor tenants and the remaining half to exclusively serve low- to moderate-income residents and environmental justice communities."}, "other": {"status": "Yes", "text": "**REF** also supported community-owned solar. Additionally, administered by Rhode Island Energy, the **Renewable Energy Growth (REG)** program enables customers to sell their generation under fixed, long-term tariffs. Participants receive bill credits up to the amount owed, and any excess generation is compensated as a direct deposit. Rhode Island has also received federal support through a $49 million Solar for All (SFA) grant. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding."}}, "details": {"size": "The maximum allowable capacity for eligible net-metering systems is 10 MW, based on nameplate capacity. Community remote distributed generation systems under the REG program must be less than 39 MW, given that they are located on preferred sites.", "eligibility": "CRNM systems may be community-owned or third-party-owned. REG program customers are not eligible to apply for a REF grant.", "benefitDist": "Under the current rules for the CRNM program, commercial and industrial anchor tenants can claim up to 50% of the output, and LMI households, residents of environmental justice communities, or disadvantaged communities claim the remaining 50%. An anchor tenant is a commercial/industrial customer that subscribes to a significant portion of the electricity output, helping ensure the company's financial viability."}, "activeCities": "The city of Cranston (Beacon Solar) and the Burrillville township (multiple facilities under CRDG) host the earliest fully subscribed installations. West Warwick hosts the first community solar array designed for an affordable housing complex (Echo Valley) in Rhode Island, and is fully subscribed as well.", "sources": [{"url": "https://energy.ri.gov/renewable-energy/net-metering", "title": "https://energy.ri.gov/renewable-energy/net-metering"}, {"url": "https://webserver.rilegislature.gov/PublicLaws/law24/law24083.htm", "title": "https://webserver.rilegislature.gov/PublicLaws/law24/law24083.htm"}, {"url": "https://commerceri.com/renewable-energy-fund/", "title": "https://commerceri.com/renewable-energy-fund/"}, {"url": "https://risolarmarketplace.com/", "title": "https://risolarmarketplace.com/"}, {"url": "https://webserver.rilegislature.gov/BillText16/HouseText16/H8354.pdf", "title": "https://webserver.rilegislature.gov/BillText16/HouseText16/H8354.pdf"}, {"url": "https://webserver.rilegislature.gov/BillText/BillText23/HouseText23/H5853.pdf", "title": "https://webserver.rilegislature.gov/BillText/BillText23/HouseText23/H5853.pdf"}, {"url": "https://webserver.rilegislature.gov/BillText23/SenateText23/S0684.htm", "title": "https://webserver.rilegislature.gov/BillText23/SenateText23/S0684.htm"}, {"url": "https://energy.ri.gov/incentives", "title": "https://energy.ri.gov/incentives"}, {"url": "https://energy.ri.gov/newsroom/energy-profiles/echo-valley-apartment-complex-installs-rooftop-solar-its-residents-and", "title": "https://energy.ri.gov/newsroom/energy-profiles/echo-valley-apartment-complex-installs-rooftop-solar-its-residents-and"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://webserver.rilegislature.gov/statutes/title39/39-26.6/39-26.6-7.htm", "title": "https://webserver.rilegislature.gov/statutes/title39/39-26.6/39-26.6-7.htm"}], "status": "active"},
  "South Carolina": {"landscape": "South Carolina is actively developing community-shared solar through state legislation. However, it has provided less targeted support for community-owned models, which individual landowners or private companies often explore.", "policies": {"vnm": {"status": "No", "text": "Although traditional net metering is mandated by state legislations, virtual or remote net metering has not yet been adopted into law.**\nSenate Bill 909** was a legislative attempt to mandate the establishment of a remote net metering program, but it ultimately failed and is now inactive."}, "cs": {"status": "Yes", "text": "Legislation enables community solar through the South Carolina Energy Freedom Act (effective May 2019), requiring the commission to initiate a proceeding for each electric utility to review the community solar programs created under Act 236 (2014) and to gather updates on current programs. **(H 3659)**\nThe state refers to the following opportunities for consumers who want to participate in community solar:\n- Dominion Energy South Carolina Community Solar—fully subscribed, accepting waitlist\n- Duke Energy Shared Solar—fully subscribed, accepting waitlist\n- Santee Cooper Solar Share—subscription lasts through 2033\n- Electric Cooperatives Community Solar—may offer community ownership, whereas the previous three offer community-shared programs."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected South Carolina for a $124 million grant under the Solar for All program. The South Carolina Office of Resilience’s Solar For All program intends to improve access and energy generation through four projects:\n- SC Community Solar Initiative\n- SC Solar Innovation Fund\n- Coordination with Energy Efficiency Programs\n- Workforce Training and Development\nIn addition, South Carolina is a member of the Southeast Rural Power Coalition, Clean Energy Fund of Texas, and Community Power Coalition. The first two received $156 million each, and the third received an additional $249 million in SFA funding."}}, "details": {"size": "Differs by program, but utilities typically cap subscriptions at 20kW.", "eligibility": "Varies by program, but typically requires membership and no participation in other solar programs.", "benefitDist": "​No specific distribution instructions are described."}, "activeCities": "Dominion Energy SC’s program is currently the most active and scalable. Key cities include Columbia and Orangeburg.", "sources": [{"url": "https://www.scstatehouse.gov/sess125_2023-2024/bills/909.htm", "title": "https://www.scstatehouse.gov/sess125_2023-2024/bills/909.htm"}, {"url": "https://www.scstatehouse.gov/sess123_2019-2020/bills/3659.htm", "title": "https://www.scstatehouse.gov/sess123_2019-2020/bills/3659.htm"}, {"url": "https://solar.sc.gov/choosing-system/community-solar", "title": "https://solar.sc.gov/choosing-system/community-solar"}, {"url": "https://dms.psc.sc.gov/Attachments/Matter/fec3d431-a004-423f-afb9-2f1c13082c62", "title": "https://dms.psc.sc.gov/Attachments/Matter/fec3d431-a004-423f-afb9-2f1c13082c62"}, {"url": "https://www.santeecooper.com/Programs-Incentives/EmpowerSolar/Solar-Home/_pdfs/Program-Manual-Solar-Home.pdf", "title": "https://www.santeecooper.com/Programs-Incentives/EmpowerSolar/Solar-Home/_pdfs/Program-Manual-Solar-Home.pdf"}, {"url": "https://scor.sc.gov/solarforall", "title": "https://scor.sc.gov/solarforall"}], "status": "active"},
  "South Dakota": {"landscape": "South Dakota lacks a state framework and incentives for community solar, resulting in few, slow-moving project developments.", "policies": {"vnm": {"status": "No", "text": "Virtual or remote net metering is not available. Traditional net metering is also not implemented by state legislation."}, "cs": {"status": "No", "text": "South Dakota has no policies enabling community solar."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists**, but federal support is available. The U.S. Environmental Protection Agency (EPA) selected South Dakota for a $62 million grant under the Solar for All program. This initiative will expand solar access for single- and multi-family homes, support low-interest financing and grants, and target low-income and disadvantaged communities. The Coalition for Green Capital (CGC) applied for a state level SFA grant on behalf of North Dakota and South Dakota. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Community solar programs are scarce. A Community Solar Array was constructed in the City of Colman by Sioux Valley Energy (SVE), offering panel subscriptions for SVE Cooperative members.", "sources": [{"url": "https://puc.sd.gov/Publications/solarfaq.aspx", "title": "https://puc.sd.gov/Publications/solarfaq.aspx"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://www.siouxvalleyenergy.com/sve-solar-projects", "title": "https://www.siouxvalleyenergy.com/sve-solar-projects"}], "status": "limited"},
  "Tennessee": {"landscape": "Tennessee's community-owned solar landscape is growing through co-ops and potential SFA-funded programs, but remains limited by a lack of enabling state policies and incentives for participation.", "policies": {"vnm": {"status": "No", "text": "Virtual or remote net metering is not enabled by state legislation."}, "cs": {"status": "No", "text": "Tennessee has no policies enabling community solar. Consumers may subscribe to community solar programs available in their area, including Nashville Electric Service’s (NES) Music City Solar, Middle Tennessee Electric’s (MTE) Cooperative Solar, and Knoxville Utilities Board’s (KUB) Community Solar."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists**, but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Tennessee for a $156 million grant under the Solar for All (SFA) program. The initiative will provide financial assistance for residential rooftop and community solar projects serving residential communities. In addition, Tennessee is a member of the multistate Community Power Coalition and Clean Energy Fund of Texas, which received $249 million and $156 million in SFA funding, respectively."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "The city of Chattanooga has Tennessee’s first operational community solar array, known as EPB Solar Share, developed by the municipal utility EPB. It generates 1.3 MW and serves more than 535 participants. Other active cities include Knoxville (KUB Community Solar developed by the municipal utility KUB) and Nashville (NES Music City Solar developed by the municipal utility NES, and MTE Cooperative Solar).", "sources": [{"url": "https://www.tn.gov/environment/program-areas/energy/state-energy-office--seo-/programs-projects/programs-and-projects/inflation-reduction-act/solar-for-all.html", "title": "https://www.tn.gov/environment/program-areas/energy/state-energy-office--seo-/programs-projects/programs-and-projects/inflation-reduction-act/solar-for-all.html"}, {"url": "https://www.tva.com/energy/valley-renewable-energy/valley-renewable-energy-for-home", "title": "https://www.tva.com/energy/valley-renewable-energy/valley-renewable-energy-for-home"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://epb.com/energy/solar-share/", "title": "https://epb.com/energy/solar-share/"}, {"url": "https://mte.com/CooperativeSolar", "title": "https://mte.com/CooperativeSolar"}, {"url": "https://www.kub.org/kub-community-solar/", "title": "https://www.kub.org/kub-community-solar/"}], "status": "limited"},
  "Texas": {"landscape": "Community-owned solar is not defined under Texas law.", "policies": {"vnm": {"status": "No", "text": "The state’s largely deregulated energy market means that retail electric providers (REPs) can choose whether or not to offer solar buyback plans, and there is no statewide policy on virtual net metering. Of the private solar buyback plans, some are uncapped, some are capped, and others are real-time metered. In the regulated parts of the state, including San Antonio and Austin, some utilities offer buyback plans. In any case, most plans do not credit solar at the full electricity rate."}, "cs": {"status": "No", "text": "There is no state-authorized community solar program in Texas."}, "other": {"status": "No", "text": "Texas does not have any legislation specifically enabling community ownership of solar, but solar devices are granted a full property tax exemption under state law. The federal government granted Texas almost $250 million under the Solar for All (SFA) program. In addition, Texas is a member of the multistate Community Power Coalition and the Clean Energy Fund of Texas, which received $249 million and $156 million in SFA funding, respectively. It is also one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million in SFA grants."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Community solar is available in the cities of El Paso, Houston, and San Antonio, and portions of Atascosa, Bexar, Collin, Comal, Culberson, Dallas, Denton, Grimes, Hudspeth, Medina, Montgomery, Tarrant, and Walker counties, among others.", "sources": [{"url": "https://statutes.capitol.texas.gov/Docs/UT/htm/UT.302.htm", "title": "Texas Utilities Code Chapter 302. Solar Power Facility Agreements"}, {"url": "https://statutes.capitol.texas.gov/Docs/LG/htm/LG.229.htm#229.001", "title": "Texas Local Government Code Chapter 229. Miscellaneous Regulatory Authority of Municipalities"}, {"url": "https://www.gosolartexas.org/community-solar", "title": "Community Solar | www.gosolartexas.org"}, {"url": "https://www.solarreviews.com/blog/texas-net-metering-complete-guide", "title": "Complete Guide To Texas Net Metering: Solar Buyback Plans, Reps & Regulated Utilities"}, {"url": "https://www.houstonchronicle.com/local/explainer/article/texas-electric-deregulation-ERCOT-TCAP-7971360.php", "title": "deregulated electricity market, explained"}, {"url": "https://cleanfundtx.org/", "title": "Clean Energy Fund of Texas"}, {"url": "https://comptroller.texas.gov/taxes/property-tax/docs/96-1569.pdf", "title": "Solar and Wind-Powered Energy Device Exemption and Appraisal Guidelines"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "Solar for All | US EPA"}], "status": "limited"},
  "United States Virgin Islands": {"landscape": "The U.S. Virgin Islands does not have any community-owned solar policies.", "policies": {"vnm": {"status": "No", "text": "While the territory has enabled traditional net metering, it does not appear to offer virtual net metering. The government has looked into the possibility of a virtual power plant but has not taken any concrete steps yet."}, "cs": {"status": "No", "text": "The U.S. Virgin Islands has no policies explicitly targeting community solar."}, "other": {"status": "No", "text": "The territory has not enabled community-owned solar through any policies."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "There do not appear to be any community solar projects in the U.S. Virgin Islands.", "sources": [{"url": "https://www.vi.gov/vi-energy-office-unveils-energy-resilient-micro-grid-at-st-croix-educational-complex/", "title": "VI Energy Office Unveils Energy Resilient Micro-Grid at St. Croix Educational Complex"}, {"url": "https://programs.dsireusa.org/system/program/detail/2507/u-s-virgin-islands-net-energy-billing", "title": "U.S. Virgin Islands - Net Energy Billing"}, {"url": "https://energy.vi.gov/wp-content/uploads/2021/12/NEBProgramOverview-webF.pdf", "title": "Net Energy Billing"}, {"url": "https://energy.vi.gov/wp-content/uploads/2025/01/USVI-VPP-Analysis-and-Recommendations-Report-2024.pdf", "title": "U.S. Virgin Islands Virtual Power Plant (VPP) Analysis and Recommendations Report"}, {"url": "https://energy.vi.gov/solar-for-all/", "title": "Solar For All - Virgin Islands"}], "status": "none"},
  "Utah": {"landscape": "According to a 2022 article, 18 communities joined the state’s community solar program, collectively representing around 25% of Rocky Mountain Power’s electricity sales in Utah.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote Net Metering is not standardized by any state legislation. However, Utah requires investor-owned utilities to offer traditional net metering to their customers **(§54-15-103)**."}, "cs": {"status": "Yes", "text": "The **Community Renewable Energy Act** created the Community Clean Energy Program, which “allows a qualified utility to provide electric service from one or more clean energy resources to a participating customer within a participating community.” Currently, the only ”qualified utility” in the state is Rocky Mountain Power. In a 2022 report, 18 out of 23 eligible communities participated in the program. The program does not use net metering or bill credits. Instead, customers pay a dedicated rate to buy clean energy. Subscription may be kept for up to 20 years. Subscriber solar customers do pay more than standard customers."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists**, but federal support is available. The S4AU Program, funded by a $62 million grant from the U.S. Environmental Protection Agency, will deliver solar through two pathways: On-site (Residential) Solar and Community Solar.\nThis will occur in years 2-5 (2026-2029) of the program. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding."}}, "details": {"size": "RMP's 20-megawatt solar plant in Millar County offers subscriptions that can be purchased in either the solar block (200 kWh) model or the full coverage model.", "eligibility": "A resident already participating in the net metering program may not be a participating customer of the Community Clean Energy Program. Residents in participating communities are automatically enrolled but may opt out. Customers have a minimum of 3 consecutive billing cycles (typically ~3 months) from program launch to opt out without penalty, and new customers (just moved in/newly served by RMP) receive their separate 3 billing cycles. After the initial opt-out period, customers can still choose to opt out, but the utility may charge a termination fee (must reflect actual unrecovered costs from clean energy purchases made on their behalf)", "benefitDist": "​No specific distribution instructions are described."}, "activeCities": "Three counties, nine cities, and six townships have committed to joining the program. The participating townships are Alta, Castle Valley, Emigration Canyon, Francis, Kearns, and Springdale. The cities are Coalville, Cottonwood Heights, Holladay, Millcreek, Moab, Oakley, Ogden, Park City, and Salt Lake City. The counties are Grand, Salt Lake, and Summit.", "sources": [{"url": "https://le.utah.gov/xcode/Title54/Chapter15/C54-15-S103_1800010118000101.pdf", "title": "https://le.utah.gov/xcode/Title54/Chapter15/C54-15-S103_1800010118000101.pdf"}, {"url": "https://le.utah.gov/xcode/Title54/Chapter17/C54-17-P9_2019051420190514.pdf", "title": "https://le.utah.gov/xcode/Title54/Chapter17/C54-17-P9_2019051420190514.pdf"}, {"url": "https://le.utah.gov/interim/2022/pdf/00002811.pdf", "title": "https://le.utah.gov/interim/2022/pdf/00002811.pdf"}, {"url": "https://energy.utah.gov/homepage/programs/solar-for-all/", "title": "https://energy.utah.gov/homepage/programs/solar-for-all/"}, {"url": "https://www.rockymountainpower.net/savings-energy-choices/blue-sky-renewable-energy/subscriber-solar.html", "title": "https://www.rockymountainpower.net/savings-energy-choices/blue-sky-renewable-energy/subscriber-solar.html"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://www.slc.gov/mayor/2022/06/10/eighteen-utah-communities-join-the-community-renewable-energy-agency-continue-working-with-rocky-mountain-power-to-meet-their-net-100-percent-clean-energy-goals/", "title": "https://www.slc.gov/mayor/2022/06/10/eighteen-utah-communities-join-the-community-renewable-energy-agency-continue-working-with-rocky-mountain-power-to-meet-their-net-100-percent-clean-energy-goals/"}], "status": "active"},
  "Vermont": {"landscape": "Despite the absence of a dedicated statewide framework, federally supported programs continue to advance community solar development, and some cooperatives have successfully developed community-owned solar projects.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote Net Metering has been sunsetted by the Vermont General Assembly with **Act 179**, which terminated the virtual Group Net Metering program for all applications after December 31, 2024, with a one-year extension for systems serving multifamily or low-income housing. The Vermont Department of Public Service (PSD) has generated a report with recommendations for replacement programs."}, "cs": {"status": "No", "text": "The state lacks a community solar framework. Historically, the statewide net metering system has enabled community solar in Vermont. **Senate Bill 50 / Act 38** expanded access to renewable energy by increasing the maximum capacity for expedited solar net metering project registrations from 15 kW to 25 kW. Although there is no state-level community solar program, **Vermont Electric Cooperative** offers the Co-op Community Solar program in which participants receive a fixed, guaranteed monthly bill credit for either 10 or 20 years. **Encore Renewable Energy**, in collaboration with **Green Mountain Power**, also has several active projects."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists, but federal support is available.** The U.S. Environmental Protection Agency (EPA) selected Vermont for a $62 million grant under the Solar for All program. This initiative supports rooftop solar (Residential Assistance in Solar Energy program), multifamily housing projects (Multi-Family Affordable Solar Housing program), and utility-led programs that provide bill savings from large-scale solar (Affordable Community Renewable Energy program). The state is also a member of the Community Power Coalition, which received $249 million in SFA funding. **Acorn Energy Co-op** has developed three community-owned solar projects located in Middlebury, Shoreham, and Bristol. At 500 kilowatts, the Bristol Community Solar project is considerably larger than the two 150 kW projects in Middlebury and Shoreham. However, AEC is not currently offering new shares for its project. Another notable community-owned solar project is the **Boardman Hill Solar Farm**. The 150 kW AC project was wholly member-owned, financed, and managed using a cooperative LLC model. Piloted in 2015, it earned a Vermont Governor’s Environmental Excellence Award in 2016."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Most development occurs within Green Mountain Power territory, including Barre and Shaftsbury. West Rutland is also an active site, home to the successful Boardman Hill Solar Farm and a new developing Boardman Hill Solar project by Encore.", "sources": [{"url": "https://publicservice.vermont.gov/renewables#:~:text=Act%20179%20Report%20%2D%20Recommendations%20for,Digital%20Infrastructure%2C%20and%20House%20Environment", "title": "https://publicservice.vermont.gov/renewables"}, {"url": "https://encorerenewableenergy.com/project-type/active/?utm_source=chatgpt.com", "title": "https://encorerenewableenergy.com/project-type/active/"}, {"url": "https://legislature.vermont.gov/Documents/2024/Docs/ACTS/ACT179/ACT179%20As%20Enacted.pdf", "title": "https://legislature.vermont.gov/Documents/2024/Docs/ACTS/ACT179/ACT179%20As%20Enacted.pdf"}, {"url": "https://publicservice.vermont.gov/renewables/solar-all-vermont", "title": "https://publicservice.vermont.gov/renewables/solar-all-vermont"}, {"url": "https://vermontelectric.coop/co-op-community-solar", "title": "https://vermontelectric.coop/co-op-community-solar"}, {"url": "https://www.acornenergycoop.com/community-solar", "title": "https://www.acornenergycoop.com/community-solar"}, {"url": "https://ilsr.org/articles/vermonts-community-solar-program/", "title": "https://ilsr.org/articles/vermonts-community-solar-program/"}, {"url": "https://vecan.net/boardman-hill-solar-farm-2/", "title": "https://vecan.net/boardman-hill-solar-farm-2/"}], "status": "limited"},
  "Virginia": {"landscape": "Currently, Virginia has no state legislation enabling community-owned solar, though a shared solar program is available, and community solar pilot programs have been implemented in the past.", "policies": {"vnm": {"status": "No", "text": "Virtual or remote net metering is not contemplated."}, "cs": {"status": "Yes", "text": "Legislation enables the Shared Solar Program:\n“The Commission shall establish by regulation a program that affords customers of a Phase II Utility the opportunity to participate in shared solar projects.” (**§ 56-594.3)**\nThe same is required of Phase I Utility **(§ 56-594.4)**. Phase I and Phase II utility each describes Appalachian Power Company and Dominion Energy Virginia.\nThis program has replaced the previous requirement, capped at fifty megawatts, for “Dominion Virginia Power and Appalachian Power to conduct a community solar pilot program for retail customers.” **(Senate Bill 1393)** **Senate Bill 253**, enacted in May 2026, expands the state's community solar program, in particular expanding Dominion Energy’s community solar capacity by up to 150 MW and mandating a continuation of Appalachian Power Company’s pilot program. Of the newly added capacity, up to 75 MW is specifically dedicated to serving low-income customers. It also allows certain projects located on rooftops, brownfields, landfills, or dual-use agricultural facilities to be eligible for incentives determined by the Virginia Department of Energy. **Senate Bill 255**, enacted in April 2026, mandates a 50-megawatt expansion of shared community solar capacity for Appalachian Power Company, after its original community solar program reached capacity almost instantly."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Virginia for a $156 million grant under the Solar for All program. Under this initiative, the SFA: Virginia Energy Program will incentivize direct ownership, third-party ownership, and subscriber-based solar energy programs. Virginia is also a member of the Southeast Rural Power Coalition, Clean Energy Fund of Texas, and Community Power Coalition. SFA granted the first two $156 million each and the third $249 million."}}, "details": {"size": "A shared solar facility must have a nameplate capacity rating of no more than 5 MW. For Phase I Utility, the shared solar program’s capacity is capped at 50 MW or 6% of peak demand, whichever is lower. For Phase II Utility, the shared solar program should have an aggregate capacity of 200 MW. Upon completion of 90% subscription, the Commission will approve an additional 150 MW of capacity.", "eligibility": "Any residential, small business, commercial, or industrial utility customer may participate.", "benefitDist": "A shared solar facility must have at least 40% of its capacity subscribed by customers with subscriptions of no more than 25 kilowatts. Phase I Utility is required to provide at least 10% net savings for low-income customers. Phase II Utility is required to have at least 30 percent of the initial aggregate capacity comprised of low-income customers, and 75 MW of the additional 150 MW serving no more than 51 % low-income customers."}, "activeCities": "Dominion’s shared solar favors urban and semi-urban centers within its service area. Southwest Virginia, under Appalachian Power, is also beginning to see activity. Although fewer in number compared to Dominion’s territory.", "sources": [{"url": "https://law.lis.virginia.gov/vacode/title56/chapter23/section56-594.3/", "title": "https://law.lis.virginia.gov/vacode/title56/chapter23/section56-594.3/"}, {"url": "https://law.lis.virginia.gov/vacode/title56/chapter23/section56-594.4/", "title": "https://law.lis.virginia.gov/vacode/title56/chapter23/section56-594.4/"}, {"url": "https://legacylis.virginia.gov/cgi-bin/legp604.exe?171+sum+SB1393", "title": "https://legacylis.virginia.gov/cgi-bin/legp604.exe?171+sum+SB1393"}, {"url": "https://www.dominionenergy.com/virginia/renewable-energy-programs/community-solar", "title": "https://www.dominionenergy.com/virginia/renewable-energy-programs/community-solar"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://ilsr.org/articles/virginias-community-solar-program/", "title": "https://ilsr.org/articles/virginias-community-solar-program/"}], "status": "active"},
  "Washington": {"landscape": "Although Washington does not mandate community solar or virtual net metering, it offers incentive programs, such as the current Community Solar Expansion program, which has generated 19 certified projects, 29 precertified projects, and an additional dozen in development.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote Net Metering is not mentioned in legislation."}, "cs": {"status": "Yes", "text": "Legislation enables community-shared programs. To expand access to the benefits of renewable energy through community solar projects, Washington passed the **Second Substitute House Bill 1814,** which enabled the **Community Solar Expansion Program** administered by Washington State University. The program states that, upon completion, a precertified project may apply for certification, and administrators will receive a one-time incentive payment from their serving utility. The payment includes two parts:\n- Up to $20,000 per community solar project to cover the administrative start-up costs.\n- A payment that covers up to 100% of the cost of the portion of the project that benefits qualifying subscribers, after accounting for any other incentives (like federal tax credits or grants).\nThere exists a statewide total cap of $100 million."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists, but a related legislation effort is pending in committee.** This proposed policy, **House Bill 1598**, aims to enable community solar by establishing comprehensive regulations and guidelines. For each community solar project, the framework requires 50 percent subscription by residential subscribers, and 30 percent by low-income subscribers, low-income service provider subscribers, or a combination of the two. Washington received $156 million in federal Solar for All (SFA) grants, which include funding for multifamily residential solar. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "The community solar project must have a direct current nameplate capacity between 12 and 199 kW.", "eligibility": "No new certification may be issued to any community solar project that was certified under RCW 82.16.120 or 82.16.165 (previous community solar pilot) or for a community solar project served by a utility that has elected not to participate in the incentive program. Administrators must be a utility, a nonprofit, a tribal housing authority, or another local housing authority. If a subscriber leaves within ten years of certification, participation must be transferred to a new qualifying subscriber. If a low-income subscriber moves within 10 years, their subscription remains in effect as long as their new home is within the same utility's service area.", "benefitDist": "Low-income subscribers, service providers, and tribal/public agency participants receive direct economic benefits. Each community solar project must have at least two low-income subscribers or one low-income service provider subscriber, and the program must set aside $2 million of the statewide total for nonprofit organizations and $2 million for tribal governments."}, "activeCities": "The City of Olympia has a dedicated nonprofit organization: Olympia Community Solar, which developed the Good Shepherd Community Solar Project and continues to advocate for supportive legislation, provide solar education, and offer funding opportunities. Separately, Puget Sound Energy, an investor-owned utility, hosts one of the largest Community Solar programs in Washington, available statewide to PSE customers. The program also includes an allocation for income-eligible customers and allows subscribers to subscribe to multiple sites. As described in a 2023 report, PSE has developed six sites (in Sammamish, Bonney Lake, Olympia, and three in Ellensburg) that generate around 16 MW of solar energy, serving nearly 4,000 customers.", "sources": [{"url": "https://www.billtrack50.com/billdetail/1801679", "title": "https://www.billtrack50.com/billdetail/1801679"}, {"url": "https://www.energy.wsu.edu/RenewableEnergy/CommunitySolarProgram.aspx", "title": "https://www.energy.wsu.edu/RenewableEnergy/CommunitySolarProgram.aspx"}, {"url": "https://lawfilesext.leg.wa.gov/biennium/2021-22/Pdf/Bills/House%20Passed%20Legislature/1814-S2.PL.pdf?q=20220701103859", "title": "https://lawfilesext.leg.wa.gov/biennium/2021-22/Pdf/Bills/House%20Passed%20Legislature/1814-S2.PL.pdf?q=20220701103859"}, {"url": "https://app.leg.wa.gov/RCW/default.aspx?cite=82.16.170", "title": "https://app.leg.wa.gov/RCW/default.aspx?cite=82.16.170"}, {"url": "https://app.leg.wa.gov/RCW/default.aspx?cite=82.16.165", "title": "https://app.leg.wa.gov/RCW/default.aspx?cite=82.16.165"}, {"url": "https://ilsr.org/articles/washingtons-community-solar-program/", "title": "https://ilsr.org/articles/washingtons-community-solar-program/"}, {"url": "https://olysol.org/", "title": "https://olysol.org/"}, {"url": "https://www.pse.com/green-options/Renewable-Energy-Programs/Community-Solar", "title": "https://www.pse.com/green-options/Renewable-Energy-Programs/Community-Solar"}, {"url": "https://www.pse.com/-/media/PDFs/PSE_Clean-Energy-Highlights-2023.ashx?sc_lang=en&rev=-1&modified=00010101000000&hash=0C644FC52E02C38A39C25B5EB279B746", "title": "https://www.pse.com/-/media/PDFs/PSE_Clean-Energy-Highlights-2023.ashx?sc_lang=en&rev=-1&modified=00010101000000&hash=0C644FC52E02C38A39C25B5EB279B746"}], "status": "active"},
  "West Virginia": {"landscape": "West Virginia allows virtual meter aggregation but lacks policies supporting community solar. Federal funding through the Solar for All program is available, and recent state legislation may affect future net metering and community solar policies.", "policies": {"vnm": {"status": "Yes", "text": "Virtual meter aggregation is permitted for net metering if the customer-generator owns or leases the properties involved. The properties must be within two miles of the customer-generator’s main or connected property and the same utility service area. If a customer-generator chooses virtual meter aggregation, the utility must provide it. Still, the customer is responsible for any additional costs associated with setting it up or managing their account under this arrangement. **(§150-33-6)**"}, "cs": {"status": "No", "text": "West Virginia has no policies enabling community solar. **House Bill 2419** and **Senate Bill 34** were reintroduced in February 2025 to promote community solar. Aside from a generation cap and sunset provision in SB 34, the bills are similar in that they require the Public Service Commission to adopt regulations governing community solar."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected West Virginia for a $106 million grant under the Solar for All program. The West Virginia REAL Energy Resilient Roofs Program (WVRRRP), funded by the SFA, aims to deliver residential and community solar to low-income and disadvantaged residents. In addition, West Virginia is part of the Industrial Heartland Solar Coalition, Clean Energy Fund of Texas, and Community Power Coalition, which received $156 million, $156 million, and $249 million, respectively, in SFA funding."}}, "details": {"size": "Net metering projects are limited to a nameplate capacity of up to 50 kW.", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "As of August 2025, West Virginia has no operational community solar programs. Areas with high solar development, such as Ravenswood City and Jefferson County, may become potential community solar sites if legislation passes.", "sources": [{"url": "https://apps.sos.wv.gov/adlaw/csr/readfile.aspx?DocId=52744&Format=PDF", "title": "https://apps.sos.wv.gov/adlaw/csr/readfile.aspx?DocId=52744&Format=PDF"}, {"url": "https://code.wvlegislature.gov/24-2F-8/", "title": "https://code.wvlegislature.gov/24-2F-8/"}, {"url": "https://www.wvlegislature.gov/Bill_Status/bills_text.cfm?billdoc=hb2568%20intr.htm&yr=2025&sesstype=RS&i=2568", "title": "https://www.wvlegislature.gov/Bill_Status/bills_text.cfm?billdoc=hb2568%20intr.htm&yr=2025&sesstype=RS&i=2568"}, {"url": "https://www.oregon.gov/puc/utilities/Pages/Renewable-Resources.aspx", "title": "https://www.oregon.gov/puc/utilities/Pages/Renewable-Resources.aspx"}, {"url": "https://www.wvlegislature.gov/Bill_Text_HTML/2025_SESSIONS/RS/bills/hb2419%20intr.pdf", "title": "https://www.wvlegislature.gov/Bill_Text_HTML/2025_SESSIONS/RS/bills/hb2419%20intr.pdf"}, {"url": "https://www.wvlegislature.gov/Bill_Text_HTML/2025_SESSIONS/RS/bills/sb34%20intr.pdf", "title": "https://www.wvlegislature.gov/Bill_Text_HTML/2025_SESSIONS/RS/bills/sb34%20intr.pdf"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://www.psc.state.wv.us/scripts/orders/ViewDocument.cfm?CaseActivityID=299384&Source=Docket", "title": "https://www.psc.state.wv.us/scripts/orders/ViewDocument.cfm?CaseActivityID=299384&Source=Docket"}], "status": "limited"},
  "Wisconsin": {"landscape": "Wisconsin does not currently have an official community solar program. Still, it enables virtual net metering and is receiving federal support through upcoming initiatives such as the WISCO program to empower community solar.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote net metering is not mentioned in legislation."}, "cs": {"status": "No", "text": "The state lacks a community solar framework. There have been legislative efforts, such as **Assembly Bill 258 (2023)**, to legalize community solar statewide, but the bill remains stalled in committee."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Wyoming for a $62 million grant under the Solar for All (SFA) program. The initiative aims to remove barriers to solar energy. The Wisconsin Inclusive Solar Community Offering (WISCO) program, funded by the grant, supports rooftop solar (residential & multifamily) and community solar projects for low‑ and moderate‑income households. The program details are still being finalized, and project funding is anticipated to begin in late 2025. Outside the Public Service Commission of Wisconsin, community-owned alternatives are available through private co-ops: Solar Share develops community-scale projects (1-5 megawatts) and allows individuals to invest in solar projects in their communities. The state is also a member of the Community Power Coalition, which received $249 million in SFA funding, and is one of the states prioritized by the Solar Access for Nationwide Affordable Housing Program, which received $250 million."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Active community solar programs have developed in a few cities, including Fond du Lac (Alliant Energy Community Solar operated by the IOU Alliant Energy), Madison (Madison Gas and Electric Shared Solar by the IOU MGE), River Falls (River Falls Community Solar developed by the River Falls Municipal Utilities), and rural areas (Bluff Prairie Community Solar Farm by the Vernon Electric Cooperative).", "sources": [{"url": "https://psc.wi.gov/Pages/ForConsumers/MoreResources/CustomerOwnedGeneration.aspx", "title": "https://psc.wi.gov/Pages/ForConsumers/MoreResources/CustomerOwnedGeneration.aspx"}, {"url": "https://docs.legis.wisconsin.gov/2023/related/proposals/ab258", "title": "https://docs.legis.wisconsin.gov/2023/related/proposals/ab258"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}, {"url": "https://osce.wi.gov/Documents/SOW-CleanEnergyPlan2022.pdf", "title": "https://osce.wi.gov/Documents/SOW-CleanEnergyPlan2022.pdf"}, {"url": "https://wedc.org/building-communities/powerup-wisconsin/", "title": "https://wedc.org/building-communities/powerup-wisconsin/"}, {"url": "https://solarshare.coop/", "title": "https://solarshare.coop/"}, {"url": "https://www.vernonelectric.org/bpcs", "title": "https://www.vernonelectric.org/bpcs"}, {"url": "https://www.alliantenergy.com/ways-to-save/community-solar", "title": "https://www.alliantenergy.com/ways-to-save/community-solar"}, {"url": "https://www.mge.com/smart-energy/clean-energy/renewable-energy-programs/shared-solar", "title": "https://www.mge.com/smart-energy/clean-energy/renewable-energy-programs/shared-solar"}, {"url": "https://rfmu.org/892/Community-Solar", "title": "https://rfmu.org/892/Community-Solar"}], "status": "limited"},
  "Wyoming": {"landscape": "Wyoming does not have any policies that specifically support community solar or community-owned solar. Still, the state enables traditional net metering and is receiving federal funding to expand solar access for low-income and Tribal communities.", "policies": {"vnm": {"status": "No", "text": "Virtual/Remote net metering is not mentioned in legislation."}, "cs": {"status": "No", "text": "Wyoming has no policies explicitly targeting community solar. As of June 2025, Wyoming’s first residential community solar project (1 MW) is still in development under Energy Conservation Works and Lower Valley Energy. Once launched, all Lower Valley Energy members can join by purchasing shares."}, "other": {"status": "No", "text": "**No specific allocation for community-owned solar exists,** but federal support is available. The U.S. Environmental Protection Agency (EPA) selected Wyoming for a $30 million grant under the Solar for All program. The initiative aims to expand access to solar energy for low-income, Tribal, and disadvantaged communities through outreach, workforce development, and technical and financial assistance."}}, "details": {"size": "N/A", "eligibility": "N/A", "benefitDist": "N/A"}, "activeCities": "Lower Valley Energy covers about five counties: Bonneville, Caribou, Lincoln, Teton, and Sublette.", "sources": [{"url": "https://wyoleg.gov/Legislation/2001/HB0195", "title": "https://wyoleg.gov/Legislation/2001/HB0195"}, {"url": "https://www.lvenergy.com/rebates-and-resources/community-solar/", "title": "https://www.lvenergy.com/rebates-and-resources/community-solar/"}, {"url": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all", "title": "https://www.epa.gov/greenhouse-gas-reduction-fund/solar-all"}], "status": "none"}
};
